select public.upsert_bank_question($json${"id":"prof2-easy-001","type":"choice","level":"easy","testament":"ot","book":"ISA","chapter":6,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo Isaías 6:2, quantas asas tinha cada serafim?","bible_ref":"Isaías 6:2","verse_text":"Serafins estavam por cima dele, cada um tinha seis asas; com duas cobriam seus rostos, com duas cobriam seus pés, e com duas voavam."},"fr":{"prompt":"Selon Ésaïe 6:2, combien d’ailes avait chaque séraphin ?","bible_ref":"Ésaïe 6:2","verse_text":"Des séraphins se tenaient au-dessus de lui; ils avaient chacun six ailes; deux dont ils se couvraient la face, deux dont ils se couvraient les pieds, et deux dont ils se servaient pour voler."},"en":{"prompt":"According to Isaiah 6:2, how many wings did each seraph have?","bible_ref":"Isaiah 6:2","verse_text":"Above it stood the seraphims: each one had six wings; with twain he covered his face, and with twain he covered his feet, and with twain he did fly."},"es":{"prompt":"Según Isaías 6:2, ¿cuántas alas tenía cada serafín?","bible_ref":"Isaías 6:2","verse_text":"Y encima de él estaban serafines: cada uno tenía seis alas; con dos cubrían sus rostros, y con dos cubrían sus pies, y con dos volaban."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Seis"},"fr":{"text":"Six"},"en":{"text":"Six"},"es":{"text":"Seis"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Três"},"fr":{"text":"Trois"},"en":{"text":"Three"},"es":{"text":"Tres"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Quatro"},"fr":{"text":"Quatre"},"en":{"text":"Four"},"es":{"text":"Cuatro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Doze"},"fr":{"text":"Douze"},"en":{"text":"Twelve"},"es":{"text":"Doce"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-002","type":"choice","level":"easy","testament":"ot","book":"ISA","chapter":40,"verse_start":31,"verse_end":31,"texts":{"pt":{"prompt":"Segundo Isaías 40:31, os que confiam no SENHOR sobem com asas como que aves?","bible_ref":"Isaías 40:31","verse_text":"Mas os que confiam no SENHOR renovarão as forças, subirão com asas como águias; correrão, e não se cansarão; caminharão, e não se fatigarão."},"fr":{"prompt":"Selon Ésaïe 40:31, ceux qui se confient en l’Éternel prennent le vol comme quels oiseaux ?","bible_ref":"Ésaïe 40:31","verse_text":"Mais ceux qui se confient en l’Éternel renouvellent leur force. Ils prennent le vol comme les aigles; Ils courent, et ne se lassent point, Ils marchent, et ne se fatiguent point."},"en":{"prompt":"According to Isaiah 40:31, they that wait upon the LORD mount up with wings as which birds?","bible_ref":"Isaiah 40:31","verse_text":"But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint."},"es":{"prompt":"Según Isaías 40:31, ¿como qué aves levantarán las alas los que esperan a Jehová?","bible_ref":"Isaías 40:31","verse_text":"Mas los que esperan á Jehová tendrán nuevas fuerzas; levantarán las alas como águilas; correrán, y no se cansarán; caminarán, y no se fatigarán."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Águias"},"fr":{"text":"Les aigles"},"en":{"text":"Eagles"},"es":{"text":"Águilas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pombas"},"fr":{"text":"Les colombes"},"en":{"text":"Doves"},"es":{"text":"Palomas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Corvos"},"fr":{"text":"Les corbeaux"},"en":{"text":"Ravens"},"es":{"text":"Cuervos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Pardais"},"fr":{"text":"Les passereaux"},"en":{"text":"Sparrows"},"es":{"text":"Gorriones"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-003","type":"choice","level":"easy","testament":"ot","book":"ISA","chapter":53,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Segundo Isaías 53:7, foi levado ao matadouro como que animal?","bible_ref":"Isaías 53:7","verse_text":"Ele foi oprimido e afligido, porém não abriu sua boca; tal como cordeiro ele foi levado ao matadouro, e como ovelha muda perante seus tosquiadores, assim ele não abriu sua boca."},"fr":{"prompt":"Selon Ésaïe 53:7, il était semblable à quel animal qu’on mène à la boucherie ?","bible_ref":"Ésaïe 53:7","verse_text":"Il a été maltraité et opprimé, Et il n’a point ouvert la bouche, Semblable à un agneau qu’on mène à la boucherie, A une brebis muette devant ceux qui la tondent; Il n’a point ouvert la bouche."},"en":{"prompt":"According to Isaiah 53:7, he is brought as what animal to the slaughter?","bible_ref":"Isaiah 53:7","verse_text":"He was oppressed, and he was afflicted, yet he opened not his mouth: he is brought as a lamb to the slaughter, and as a sheep before her shearers is dumb, so he openeth not his mouth."},"es":{"prompt":"Según Isaías 53:7, ¿como qué animal fue llevado al matadero?","bible_ref":"Isaías 53:7","verse_text":"Angustiado él, y afligido, no abrió su boca: como cordero fué llevado al matadero; y como oveja delante de sus trasquiladores, enmudeció, y no abrió su boca."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um cordeiro"},"fr":{"text":"Un agneau"},"en":{"text":"A lamb"},"es":{"text":"Un cordero"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um leão"},"fr":{"text":"Un lion"},"en":{"text":"A lion"},"es":{"text":"Un león"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um bode"},"fr":{"text":"Un bouc"},"en":{"text":"A goat"},"es":{"text":"Un macho cabrío"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um boi"},"fr":{"text":"Un bœuf"},"en":{"text":"An ox"},"es":{"text":"Un buey"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-004","type":"choice","level":"easy","testament":"ot","book":"ISA","chapter":1,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Segundo Isaías 1:18, os pecados como a escarlate ficarão brancos como quê?","bible_ref":"Isaías 1:18","verse_text":"Vinde, então, e façamos as contas, diz o SENHOR: ainda que vossos pecados sejam como a escarlate, eles ficarão brancos como a neve; ainda que sejam vermelhos como o carmesim, eles se tornarão como a lã."},"fr":{"prompt":"Selon Ésaïe 1:18, les péchés comme le cramoisi deviendront blancs comme quoi ?","bible_ref":"Ésaïe 1:18","verse_text":"Venez et plaidons! Dit l’Éternel. Si vos péchés sont comme le cramoisi, ils deviendront blancs comme la neige; S’ils sont rouges comme la pourpre, ils deviendront comme la laine."},"en":{"prompt":"According to Isaiah 1:18, sins as scarlet shall be as white as what?","bible_ref":"Isaiah 1:18","verse_text":"Come now, and let us reason together, saith the LORD: though your sins be as scarlet, they shall be as white as snow; though they be red like crimson, they shall be as wool."},"es":{"prompt":"Según Isaías 1:18, ¿como qué serán emblanquecidos los pecados como la grana?","bible_ref":"Isaías 1:18","verse_text":"Venid luego, dirá Jehová, y estemos á cuenta: si vuestros pecados fueren como la grana, como la nieve serán emblanquecidos: si fueren rojos como el carmesí, vendrán á ser como blanca lana."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A neve"},"fr":{"text":"La neige"},"en":{"text":"Snow"},"es":{"text":"La nieve"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O leite"},"fr":{"text":"Le lait"},"en":{"text":"Milk"},"es":{"text":"La leche"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"As nuvens"},"fr":{"text":"Les nuages"},"en":{"text":"Clouds"},"es":{"text":"Las nubes"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O sal"},"fr":{"text":"Le sel"},"en":{"text":"Salt"},"es":{"text":"La sal"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-005","type":"choice","level":"easy","testament":"ot","book":"ISA","chapter":40,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Segundo Isaías 40:11, ele apascentará o seu rebanho como quem?","bible_ref":"Isaías 40:11","verse_text":"Como pastor ele apascentará seu rebanho; em seus braços recolherá aos cordeirinhos, e os levará em seu colo; ele guiará mansamente as que tiveram filhotes."},"fr":{"prompt":"Selon Ésaïe 40:11, il paîtra son troupeau comme qui ?","bible_ref":"Ésaïe 40:11","verse_text":"Comme un berger, il paîtra son troupeau, Il prendra les agneaux dans ses bras, Et les portera dans son sein; Il conduira les brebis qui allaitent."},"en":{"prompt":"According to Isaiah 40:11, he shall feed his flock like whom?","bible_ref":"Isaiah 40:11","verse_text":"He shall feed his flock like a shepherd: he shall gather the lambs with his arm, and carry them in his bosom, and shall gently lead those that are with young."},"es":{"prompt":"Según Isaías 40:11, ¿como quién apacentará su rebaño?","bible_ref":"Isaías 40:11","verse_text":"Como pastor apacentará su rebaño; en su brazo cogerá los corderos, y en su seno los llevará; pastoreará suavemente las paridas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um pastor"},"fr":{"text":"Un berger"},"en":{"text":"A shepherd"},"es":{"text":"Un pastor"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um rei"},"fr":{"text":"Un roi"},"en":{"text":"A king"},"es":{"text":"Un rey"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um pescador"},"fr":{"text":"Un pêcheur"},"en":{"text":"A fisherman"},"es":{"text":"Un pescador"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um soldado"},"fr":{"text":"Un soldat"},"en":{"text":"A soldier"},"es":{"text":"Un soldado"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-006","type":"choice","level":"easy","testament":"ot","book":"JER","chapter":13,"verse_start":23,"verse_end":23,"texts":{"pt":{"prompt":"Segundo Jeremias 13:23, que animal não pode mudar as suas manchas?","bible_ref":"Jeremias 13:23","verse_text":"Pode o negro mudar a sua pele, ou o leopardo suas manchas? Assim também podeis vós fazer o bem, sendo tão acostumados a praticar o mal?"},"fr":{"prompt":"Selon Jérémie 13:23, quel animal ne peut pas changer ses taches ?","bible_ref":"Jérémie 13:23","verse_text":"Un Éthiopien peut-il changer sa peau, Et un léopard ses taches? De même, pourriez-vous faire le bien, Vous qui êtes accoutumés à faire le mal?"},"en":{"prompt":"According to Jeremiah 13:23, which animal cannot change his spots?","bible_ref":"Jeremiah 13:23","verse_text":"Can the Ethiopian change his skin, or the leopard his spots? then may ye also do good, that are accustomed to do evil."},"es":{"prompt":"Según Jeremías 13:23, ¿qué animal no puede mudar sus manchas?","bible_ref":"Jeremías 13:23","verse_text":"¿Mudará el negro su pellejo, y el leopardo sus manchas? Así también podréis vosotros hacer bien, estando habituados á hacer mal."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O leopardo"},"fr":{"text":"Le léopard"},"en":{"text":"The leopard"},"es":{"text":"El leopardo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O leão"},"fr":{"text":"Le lion"},"en":{"text":"The lion"},"es":{"text":"El león"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A zebra"},"fr":{"text":"Le zèbre"},"en":{"text":"The zebra"},"es":{"text":"La cebra"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O camelo"},"fr":{"text":"Le chameau"},"en":{"text":"The camel"},"es":{"text":"El camello"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-007","type":"choice","level":"easy","testament":"ot","book":"JER","chapter":1,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo Jeremias 1:9, o que tocou o SENHOR com a sua mão?","bible_ref":"Jeremias 1:9","verse_text":"Então o SENHOR estendeu sua mão, e tocou em minha boca. E o SENHOR me disse: Eis que tenho posto minhas palavras em tua boca."},"fr":{"prompt":"Selon Jérémie 1:9, qu’est-ce que l’Éternel toucha de sa main ?","bible_ref":"Jérémie 1:9","verse_text":"Puis l’Éternel étendit sa main, et toucha ma bouche; et l’Éternel me dit: Voici, je mets mes paroles dans ta bouche."},"en":{"prompt":"According to Jeremiah 1:9, what did the LORD touch with his hand?","bible_ref":"Jeremiah 1:9","verse_text":"Then the LORD put forth his hand, and touched my mouth. And the LORD said unto me, Behold, I have put my words in thy mouth."},"es":{"prompt":"Según Jeremías 1:9, ¿qué tocó Jehová con su mano?","bible_ref":"Jeremías 1:9","verse_text":"Y extendió Jehová su mano, y tocó sobre mi boca; y díjome Jehová: He aquí he puesto mis palabras en tu boca."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A boca de Jeremias"},"fr":{"text":"La bouche de Jérémie"},"en":{"text":"Jeremiah’s mouth"},"es":{"text":"La boca de Jeremías"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os olhos de Jeremias"},"fr":{"text":"Les yeux de Jérémie"},"en":{"text":"Jeremiah’s eyes"},"es":{"text":"Los ojos de Jeremías"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os ouvidos de Jeremias"},"fr":{"text":"Les oreilles de Jérémie"},"en":{"text":"Jeremiah’s ears"},"es":{"text":"Los oídos de Jeremías"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"As mãos de Jeremias"},"fr":{"text":"Les mains de Jérémie"},"en":{"text":"Jeremiah’s hands"},"es":{"text":"Las manos de Jeremías"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-008","type":"choice","level":"easy","testament":"ot","book":"JON","chapter":1,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Segundo Jonas 1:5, o que fazia Jonas no fundo do navio enquanto os marinheiros tinham medo?","bible_ref":"Jonas 1:5","verse_text":"Então os marinheiros tiveram medo, e cada um clamava a seu deus; e lançaram no mar os objetos que havia no navio, para com eles diminuir o peso. Jonas, porém, havia descido ao interior do navio, e se pôs a dormir profundamente."},"fr":{"prompt":"Selon Jonas 1:5, que faisait Jonas au fond du navire pendant que les mariniers avaient peur ?","bible_ref":"Jonas 1:5","verse_text":"Les mariniers eurent peur, ils implorèrent chacun leur dieu, et ils jetèrent dans la mer les objets qui étaient sur le navire, afin de se le rendre plus léger. Jonas descendit au fond du navire, se coucha, et s’endormit profondément."},"en":{"prompt":"According to Jonah 1:5, what was Jonah doing in the sides of the ship while the mariners were afraid?","bible_ref":"Jonah 1:5","verse_text":"Then the mariners were afraid, and cried every man unto his god, and cast forth the wares that were in the ship into the sea, to lighten it of them. But Jonah was gone down into the sides of the ship; and he lay, and was fast asleep."},"es":{"prompt":"Según Jonás 1:5, ¿qué hacía Jonás abajo en el buque mientras los marineros tenían miedo?","bible_ref":"Jonás 1:5","verse_text":"Y los marineros tuvieron miedo, y cada uno llamaba á su dios: y echaron á la mar los enseres que había en la nave, para descargarla de ellos. Jonás empero se había bajado á los lados del buque, y se había echado á dormir."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dormia"},"fr":{"text":"Il dormait"},"en":{"text":"He was asleep"},"es":{"text":"Dormía"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Orava"},"fr":{"text":"Il priait"},"en":{"text":"He was praying"},"es":{"text":"Oraba"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Comia"},"fr":{"text":"Il mangeait"},"en":{"text":"He was eating"},"es":{"text":"Comía"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Remava"},"fr":{"text":"Il ramait"},"en":{"text":"He was rowing"},"es":{"text":"Remaba"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-009","type":"choice","level":"easy","testament":"ot","book":"MIC","chapter":4,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo Miqueias 4:4, debaixo de quê se sentará cada um, sem ninguém que lhe cause medo?","bible_ref":"Miqueias 4:4","verse_text":"E cada um se sentará debaixo de sua videira e debaixo de sua figueira, e não haverá quem lhes cause medo; porque a boca do SENHOR dos exércitos assim falou."},"fr":{"prompt":"Selon Michée 4:4, sous quoi chacun habitera-t-il, sans personne pour le troubler ?","bible_ref":"Michée 4:4","verse_text":"Ils habiteront chacun sous sa vigne et sous son figuier, Et il n’y aura personne pour les troubler; Car la bouche de l’Éternel des armées a parlé."},"en":{"prompt":"According to Micah 4:4, under what shall every man sit, with none to make him afraid?","bible_ref":"Micah 4:4","verse_text":"But they shall sit every man under his vine and under his fig tree; and none shall make them afraid: for the mouth of the LORD of hosts hath spoken it."},"es":{"prompt":"Según Miqueas 4:4, ¿debajo de qué se sentará cada uno, sin que nadie lo amedrente?","bible_ref":"Miqueas 4:4","verse_text":"Y cada uno se sentará debajo de su vid y debajo de su higuera, y no habrá quien amedrente: porque la boca de Jehová de los ejércitos lo ha hablado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A sua videira e a sua figueira"},"fr":{"text":"Sa vigne et son figuier"},"en":{"text":"His vine and his fig tree"},"es":{"text":"Su vid y su higuera"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O seu carvalho e o seu cedro"},"fr":{"text":"Son chêne et son cèdre"},"en":{"text":"His oak and his cedar"},"es":{"text":"Su encina y su cedro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A sua palmeira e a sua oliveira"},"fr":{"text":"Son palmier et son olivier"},"en":{"text":"His palm tree and his olive tree"},"es":{"text":"Su palmera y su olivo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A sua tenda"},"fr":{"text":"Sa tente"},"en":{"text":"His tent"},"es":{"text":"Su tienda"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-010","type":"choice","level":"easy","testament":"ot","book":"MIC","chapter":7,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Segundo Miqueias 7:19, para onde serão lançados os pecados?","bible_ref":"Miqueias 7:19","verse_text":"Ele voltará a ter misericórdia de nós; ele esmagará nossas maldades. Tu lançarás os pecados deles nas profundezas do mar."},"fr":{"prompt":"Selon Michée 7:19, où les péchés seront-ils jetés ?","bible_ref":"Michée 7:19","verse_text":"Il aura encore compassion de nous, Il mettra sous ses pieds nos iniquités; Tu jetteras au fond de la mer tous leurs péchés."},"en":{"prompt":"According to Micah 7:19, where will the sins be cast?","bible_ref":"Micah 7:19","verse_text":"He will turn again, he will have compassion upon us; he will subdue our iniquities; and thou wilt cast all their sins into the depths of the sea."},"es":{"prompt":"Según Miqueas 7:19, ¿dónde serán echados los pecados?","bible_ref":"Miqueas 7:19","verse_text":"El tornará, él tendrá misericordia de nosotros; él sujetará nuestras iniquidades, y echará en los profundos de la mar todos nuestros pecados."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nas profundezas do mar"},"fr":{"text":"Au fond de la mer"},"en":{"text":"Into the depths of the sea"},"es":{"text":"En los profundos de la mar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"No fogo"},"fr":{"text":"Dans le feu"},"en":{"text":"Into the fire"},"es":{"text":"En el fuego"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No deserto"},"fr":{"text":"Au désert"},"en":{"text":"Into the wilderness"},"es":{"text":"En el desierto"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Atrás das montanhas"},"fr":{"text":"Derrière les montagnes"},"en":{"text":"Behind the mountains"},"es":{"text":"Detrás de los montes"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-011","type":"choice","level":"easy","testament":"ot","book":"ZEC","chapter":8,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Segundo Zacarias 8:5, de quem estariam cheias as ruas da cidade?","bible_ref":"Zacarias 8:5","verse_text":"E as ruas da cidade se encherão de meninos e meninas, brincando em suas ruas."},"fr":{"prompt":"Selon Zacharie 8:5, de qui les rues de la ville seraient-elles remplies ?","bible_ref":"Zacharie 8:5","verse_text":"Les rues de la ville seront remplies de jeunes garçons et de jeunes filles, jouant dans les rues."},"en":{"prompt":"According to Zechariah 8:5, the streets of the city shall be full of whom?","bible_ref":"Zechariah 8:5","verse_text":"And the streets of the city shall be full of boys and girls playing in the streets thereof."},"es":{"prompt":"Según Zacarías 8:5, ¿de quiénes estarán llenas las calles de la ciudad?","bible_ref":"Zacarías 8:5","verse_text":"Y las calles de la ciudad serán llenas de muchachos y muchachas, que jugarán en las calles."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Meninos e meninas a brincar"},"fr":{"text":"De garçons et de filles qui jouent"},"en":{"text":"Boys and girls playing"},"es":{"text":"Muchachos y muchachas que juegan"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Soldados a marchar"},"fr":{"text":"De soldats qui marchent"},"en":{"text":"Soldiers marching"},"es":{"text":"Soldados que marchan"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Mercadores a vender"},"fr":{"text":"De marchands qui vendent"},"en":{"text":"Merchants selling"},"es":{"text":"Mercaderes que venden"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ovelhas a pastar"},"fr":{"text":"De brebis qui paissent"},"en":{"text":"Sheep grazing"},"es":{"text":"Ovejas que pacen"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-012","type":"choice","level":"easy","testament":"ot","book":"EZK","chapter":37,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo Ezequiel 37:10, quando o espírito entrou neles, em que se tornaram?","bible_ref":"Ezequiel 37:10","verse_text":"E profetizei como havia me sido mandado; então o espírito entrou neles, e viveram, e se puseram de pé, um exército extremamente grande."},"fr":{"prompt":"Selon Ézéchiel 37:10, quand l’esprit entra en eux, que devinrent-ils ?","bible_ref":"Ézéchiel 37:10","verse_text":"Je prophétisai, selon l’ordre qu’il m’avait donné. Et l’esprit entra en eux, et ils reprirent vie, et ils se tinrent sur leurs pieds: c’était une armée nombreuse, très nombreuse."},"en":{"prompt":"According to Ezekiel 37:10, when the breath came into them, what did they become?","bible_ref":"Ezekiel 37:10","verse_text":"So I prophesied as he commanded me, and the breath came into them, and they lived, and stood up upon their feet, an exceeding great army."},"es":{"prompt":"Según Ezequiel 37:10, cuando entró espíritu en ellos, ¿en qué se convirtieron?","bible_ref":"Ezequiel 37:10","verse_text":"Y profeticé como me había mandado, y entró espíritu en ellos, y vivieron, y estuvieron sobre sus pies, un ejército grande en extremo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um exército muito grande"},"fr":{"text":"Une armée très nombreuse"},"en":{"text":"An exceeding great army"},"es":{"text":"Un ejército grande en extremo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um rebanho de ovelhas"},"fr":{"text":"Un troupeau de brebis"},"en":{"text":"A flock of sheep"},"es":{"text":"Un rebaño de ovejas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma floresta"},"fr":{"text":"Une forêt"},"en":{"text":"A forest"},"es":{"text":"Un bosque"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um monte de pó"},"fr":{"text":"Un tas de poussière"},"en":{"t