select public.upsert_bank_question($json${"id":"prof2-easy-013","type":"choice","level":"easy","testament":"ot","book":"DAN","chapter":9,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"Segundo Daniel 9:21, quem veio a voar até Daniel enquanto ele orava?","bible_ref":"Daniel 9:21","verse_text":"Estava eu falando em oração, e aquele varão Gabriel, ao qual eu tinha visto em visão antes, veio voando apressadamente, e me tocou cerca da hora do sacrifício da tarde."},"fr":{"prompt":"Selon Daniel 9:21, qui s’approcha de Daniel d’un vol rapide pendant qu’il priait ?","bible_ref":"Daniel 9:21","verse_text":"je parlais encore dans ma prière, quand l’homme, Gabriel, que j’avais vu précédemment dans une vision, s’approcha de moi d’un vol rapide, au moment de l’offrande du soir."},"en":{"prompt":"According to Daniel 9:21, who came flying swiftly to Daniel while he was praying?","bible_ref":"Daniel 9:21","verse_text":"Yea, whiles I was speaking in prayer, even the man Gabriel, whom I had seen in the vision at the beginning, being caused to fly swiftly, touched me about the time of the evening oblation."},"es":{"prompt":"Según Daniel 9:21, ¿quién vino volando a Daniel mientras oraba?","bible_ref":"Daniel 9:21","verse_text":"Aun estaba hablando en oración, y aquel varón Gabriel, al cual había visto en visión al principio, volando con presteza, me tocó como á la hora del sacrificio de la tarde."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Gabriel"},"fr":{"text":"Gabriel"},"en":{"text":"Gabriel"},"es":{"text":"Gabriel"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Miguel"},"fr":{"text":"Micaël"},"en":{"text":"Michael"},"es":{"text":"Miguel"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Elias"},"fr":{"text":"Élie"},"en":{"text":"Elijah"},"es":{"text":"Elías"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-014","type":"choice","level":"easy","testament":"ot","book":"DAN","chapter":12,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Daniel 12:3, como o que brilharão os que conduzem muitos à justiça?","bible_ref":"Daniel 12:3","verse_text":"E os sábios brilharão como o resplendor do céu; e os que conduzem muitos à justiça brilharão como as estrelas, para todo o sempre."},"fr":{"prompt":"Selon Daniel 12:3, comme quoi brilleront ceux qui auront enseigné la justice à la multitude ?","bible_ref":"Daniel 12:3","verse_text":"Ceux qui auront été intelligents brilleront comme la splendeur du ciel, et ceux qui auront enseigné la justice, à la multitude brilleront comme les étoiles, à toujours et à perpétuité."},"en":{"prompt":"According to Daniel 12:3, they that turn many to righteousness shall shine as what?","bible_ref":"Daniel 12:3","verse_text":"And they that be wise shall shine as the brightness of the firmament; and they that turn many to righteousness as the stars for ever and ever."},"es":{"prompt":"Según Daniel 12:3, ¿como qué resplandecerán los que enseñan a justicia la multitud?","bible_ref":"Daniel 12:3","verse_text":"Y los entendidos resplandecerán como el resplandor del firmamento; y los que enseñan á justicia la multitud, como las estrellas á perpetua eternidad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"As estrelas"},"fr":{"text":"Les étoiles"},"en":{"text":"The stars"},"es":{"text":"Las estrellas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O sol"},"fr":{"text":"Le soleil"},"en":{"text":"The sun"},"es":{"text":"El sol"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os relâmpagos"},"fr":{"text":"Les éclairs"},"en":{"text":"The lightning"},"es":{"text":"Los relámpagos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O fogo"},"fr":{"text":"Le feu"},"en":{"text":"The fire"},"es":{"text":"El fuego"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-015","type":"choice","level":"easy","testament":"ot","book":"JOL","chapter":1,"verse_start":4,"verse_end":4,"texts":{"pt":{"prompt":"Segundo Joel 1:4, que insetos comeram o que restava da colheita?","bible_ref":"Joel 1:4","verse_text":"O que restou do gafanhoto cortador o gafanhoto comedor comeu; e o que restou do gafanhoto comedor o gafanhoto devorador comeu, e o que restou do gafanhoto devorador o gafanhoto destruidor comeu."},"fr":{"prompt":"Selon Joël 1:4, quels insectes ont dévoré ce qui restait ?","bible_ref":"Joël 1:4","verse_text":"Ce qu’a laissé le gazam, la sauterelle l’a dévoré; Ce qu’a laissé la sauterelle, le jélek l’a dévoré; Ce qu’a laissé le jélek, le hasil l’a dévoré."},"en":{"prompt":"According to Joel 1:4, which insects ate what was left?","bible_ref":"Joel 1:4","verse_text":"That which the palmerworm hath left hath the locust eaten; and that which the locust hath left hath the cankerworm eaten; and that which the cankerworm hath left hath the caterpiller eaten."},"es":{"prompt":"Según Joel 1:4, ¿qué insectos comieron lo que quedaba?","bible_ref":"Joel 1:4","verse_text":"Lo que quedó de la oruga comió la langosta, y lo que quedó de la langosta comió el pulgón; y el revoltón comió lo que del pulgón había quedado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Gafanhotos"},"fr":{"text":"Des sauterelles"},"en":{"text":"Locusts"},"es":{"text":"Langostas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Abelhas"},"fr":{"text":"Des abeilles"},"en":{"text":"Bees"},"es":{"text":"Abejas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Moscas"},"fr":{"text":"Des mouches"},"en":{"text":"Flies"},"es":{"text":"Moscas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Formigas"},"fr":{"text":"Des fourmis"},"en":{"text":"Ants"},"es":{"text":"Hormigas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-016","type":"choice","level":"easy","testament":"ot","book":"HAB","chapter":2,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo Habacuque 2:2, o que mandou o SENHOR fazer com a visão?","bible_ref":"Habacuque 2:2","verse_text":"Então o SENHOR me respondeu, e disse: Escreve a visão, e a põe claramente em tábuas, para que mesmo quem esteja correndo consiga ler."},"fr":{"prompt":"Selon Habacuc 2:2, que dit l’Éternel de faire de la prophétie ?","bible_ref":"Habacuc 2:2","verse_text":"L’Éternel m’adressa la parole, et il dit: Écris la prophétie: Grave-la sur des tables, Afin qu’on la lise couramment."},"en":{"prompt":"According to Habakkuk 2:2, what did the LORD say to do with the vision?","bible_ref":"Habakkuk 2:2","verse_text":"And the LORD answered me, and said, Write the vision, and make it plain upon tables, that he may run that readeth it."},"es":{"prompt":"Según Habacuc 2:2, ¿qué dijo Jehová que hiciera con la visión?","bible_ref":"Habacuc 2:2","verse_text":"Y Jehová me respondió, y dijo: Escribe la visión, y declárala en tablas, para que corra el que leyere en ella."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Escrevê-la em tábuas"},"fr":{"text":"L’écrire sur des tables"},"en":{"text":"Write it upon tables"},"es":{"text":"Escribirla en tablas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Guardá-la em segredo"},"fr":{"text":"La garder secrète"},"en":{"text":"Keep it secret"},"es":{"text":"Guardarla en secreto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cantá-la no templo"},"fr":{"text":"La chanter dans le temple"},"en":{"text":"Sing it in the temple"},"es":{"text":"Cantarla en el templo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Esquecê-la"},"fr":{"text":"L’oublier"},"en":{"text":"Forget it"},"es":{"text":"Olvidarla"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-017","type":"choice","level":"easy","testament":"ot","book":"MAL","chapter":4,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Segundo Malaquias 4:5, que profeta enviará Deus antes do grande dia do SENHOR?","bible_ref":"Malaquias 4:5","verse_text":"Eis que eu vos envio o profeta Elias, antes que venha o grande e temível dia do SENHOR."},"fr":{"prompt":"Selon Malachie 4:5, quel prophète Dieu enverra-t-il avant le grand jour de l’Éternel ?","bible_ref":"Malachie 4:5","verse_text":"Voici, je vous enverrai Élie, le prophète, Avant que le jour de l’Éternel arrive, Ce jour grand et redoutable."},"en":{"prompt":"According to Malachi 4:5, which prophet will God send before the great day of the LORD?","bible_ref":"Malachi 4:5","verse_text":"Behold, I will send you Elijah the prophet before the coming of the great and dreadful day of the LORD:"},"es":{"prompt":"Según Malaquías 4:5, ¿qué profeta enviará Dios antes del gran día de Jehová?","bible_ref":"Malaquías 4:5","verse_text":"He aquí, yo os envío á Elías el profeta, antes que venga el día de Jehová grande y terrible."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Elias"},"fr":{"text":"Élie"},"en":{"text":"Elijah"},"es":{"text":"Elías"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Moisés"},"fr":{"text":"Moïse"},"en":{"text":"Moses"},"es":{"text":"Moisés"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Isaías"},"fr":{"text":"Ésaïe"},"en":{"text":"Isaiah"},"es":{"text":"Isaías"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Jonas"},"fr":{"text":"Jonas"},"en":{"text":"Jonah"},"es":{"text":"Jonás"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-018","type":"choice","level":"easy","testament":"ot","book":"HOS","chapter":11,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Oseias 11:1, de que terra chamou Deus o seu filho?","bible_ref":"Oseias 11:1","verse_text":"Quando Israel era menino, eu o amei, e do Egito chamei a meu filho."},"fr":{"prompt":"Selon Osée 11:1, de quel pays Dieu appela-t-il son fils ?","bible_ref":"Osée 11:1","verse_text":"Quand Israël était jeune, je l’aimais, Et j’appelai mon fils hors d’Égypte."},"en":{"prompt":"According to Hosea 11:1, out of which land did God call his son?","bible_ref":"Hosea 11:1","verse_text":"When Israel was a child, then I loved him, and called my son out of Egypt."},"es":{"prompt":"Según Oseas 11:1, ¿de qué tierra llamó Dios a su hijo?","bible_ref":"Oseas 11:1","verse_text":"Cuando Israel era muchacho, yo lo amé, y de Egipto llamé á mi hijo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Do Egito"},"fr":{"text":"D’Égypte"},"en":{"text":"Out of Egypt"},"es":{"text":"De Egipto"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Da Babilónia"},"fr":{"text":"De Babylone"},"en":{"text":"Out of Babylon"},"es":{"text":"De Babilonia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Da Assíria"},"fr":{"text":"D’Assyrie"},"en":{"text":"Out of Assyria"},"es":{"text":"De Asiria"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De Moabe"},"fr":{"text":"De Moab"},"en":{"text":"Out of Moab"},"es":{"text":"De Moab"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-easy-019","type":"verse","level":"easy","testament":"ot","book":"ISA","chapter":41,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Não temas, porque eu estou contigo; não te assombres, porque eu sou teu _____. Eu te fortaleço, te ajudo, e te sustento com a minha mão direita de justiça.","bible_ref":"Isaías 41:10","verse_text":"Não temas, porque eu estou contigo; não te assombres, porque eu sou teu Deus. Eu te fortaleço, te ajudo, e te sustento com a minha mão direita de justiça."},"fr":{"prompt":"Ne crains rien, car je suis avec toi; Ne promène pas des regards inquiets, car je suis ton _____; Je te fortifie, je viens à ton secours, Je te soutiens de ma droite triomphante.","bible_ref":"Ésaïe 41:10","verse_text":"Ne crains rien, car je suis avec toi; Ne promène pas des regards inquiets, car je suis ton Dieu; Je te fortifie, je viens à ton secours, Je te soutiens de ma droite triomphante."},"en":{"prompt":"Fear thou not; for I am with thee: be not dismayed; for I am thy _____: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.","bible_ref":"Isaiah 41:10","verse_text":"Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness."},"es":{"prompt":"No temas, que yo soy contigo; no desmayes, que yo soy tu _____ que te esfuerzo: siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia.","bible_ref":"Isaías 41:10","verse_text":"No temas, que yo soy contigo; no desmayes, que yo soy tu Dios que te esfuerzo: siempre te ayudaré, siempre te sustentaré con la diestra de mi justicia."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"rei"},"fr":{"text":"roi"},"en":{"text":"king"},"es":{"text":"rey"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"amigo"},"fr":{"text":"ami"},"en":{"text":"friend"},