select public.upsert_bank_question($json${"id":"prof2-easy-024","type":"verse","level":"easy","testament":"ot","book":"ZEP","chapter":3,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"O SENHOR está no meio de ti, guerreiro que _____; ele terá prazer em ti com alegria; ele te aquietará em seu amor, se encherá de alegria por causa de ti com júbilo.","bible_ref":"Sofonias 3:17","verse_text":"O SENHOR está no meio de ti, guerreiro que salva; ele terá prazer em ti com alegria; ele te aquietará em seu amor, se encherá de alegria por causa de ti com júbilo."},"fr":{"prompt":"L’Éternel, ton Dieu, est au milieu de toi, comme un héros qui _____; Il fera de toi sa plus grande joie; Il gardera le silence dans son amour; Il aura pour toi des transports d’allégresse.","bible_ref":"Sophonie 3:17","verse_text":"L’Éternel, ton Dieu, est au milieu de toi, comme un héros qui sauve; Il fera de toi sa plus grande joie; Il gardera le silence dans son amour; Il aura pour toi des transports d’allégresse."},"en":{"prompt":"The LORD thy God in the midst of thee is mighty; he will _____, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing.","bible_ref":"Zephaniah 3:17","verse_text":"The LORD thy God in the midst of thee is mighty; he will save, he will rejoice over thee with joy; he will rest in his love, he will joy over thee with singing."},"es":{"prompt":"Jehová en medio de ti, poderoso, él _____; gozaráse sobre ti con alegría, callará de amor, se regocijará sobre ti con cantar.","bible_ref":"Sofonías 3:17","verse_text":"Jehová en medio de ti, poderoso, él salvará; gozaráse sobre ti con alegría, callará de amor, se regocijará sobre ti con cantar."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"salva"},"fr":{"text":"sauve"},"en":{"text":"save"},"es":{"text":"salvará"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"dorme"},"fr":{"text":"dort"},"en":{"text":"sleep"},"es":{"text":"dormirá"}}},{"position":3,"i