select public.upsert_bank_question($json${"id":"prof2-medium-001","type":"choice","level":"medium","testament":"ot","book":"ISA","chapter":6,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Isaías 6:1, em que ano viu Isaías o Senhor sentado num alto trono?","bible_ref":"Isaías 6:1","verse_text":"No ano em que o rei Uzias morreu, eu vi o Senhor sentado sobre um alto e elevado trono; e as bordas de seu manto enchiam o templo."},"fr":{"prompt":"Selon Ésaïe 6:1, en quelle année Ésaïe vit-il le Seigneur assis sur un trône très élevé ?","bible_ref":"Ésaïe 6:1","verse_text":"L’année de la mort du roi Ozias, je vis le Seigneur assis sur un trône très élevé, et les pans de sa robe remplissaient le temple."},"en":{"prompt":"According to Isaiah 6:1, in what year did Isaiah see the Lord sitting upon a high throne?","bible_ref":"Isaiah 6:1","verse_text":"In the year that king Uzziah died I saw also the Lord sitting upon a throne, high and lifted up, and his train filled the temple."},"es":{"prompt":"Según Isaías 6:1, ¿en qué año vio Isaías al Señor sentado sobre un trono alto?","bible_ref":"Isaías 6:1","verse_text":"En el año que murió el rey Uzzías vi yo al Señor sentado sobre un trono alto y sublime, y sus faldas henchían el templo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"No ano em que morreu o rei Uzias"},"fr":{"text":"L’année de la mort du roi Ozias"},"en":{"text":"In the year that king Uzziah died"},"es":{"text":"En el año que murió el rey Uzzías"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"No ano em que morreu o rei Saul"},"fr":{"text":"L’année de la mort du roi Saül"},"en":{"text":"In the year that king Saul died"},"es":{"text":"En el año que murió el rey Saúl"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"No ano em que morreu o rei Salomão"},"fr":{"text":"L’année de la mort du roi Salomon"},"en":{"text":"In the year that king Solomon died"},"es":{"text":"En el año que murió el rey Salomón"}}},{"positi