select public.upsert_bank_question($json${"id":"prof2-medium-002","type":"choice","level":"medium","testament":"ot","book":"ISA","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Isaías 1:3, que animal conhece o seu dono, enquanto Israel não conhece?","bible_ref":"Isaías 1:3","verse_text":"O boi conhece a seu dono, e o jumento sabe a manjedoura de seu possuidor; mas Israel não conhece, meu povo não entende."},"fr":{"prompt":"Selon Ésaïe 1:3, quel animal connaît son possesseur, alors qu’Israël ne connaît rien ?","bible_ref":"Ésaïe 1:3","verse_text":"Le bœuf connaît son possesseur, Et l’âne la crèche de son maître: Israël ne connaît rien, Mon peuple n’a point d’intelligence."},"en":{"prompt":"According to Isaiah 1:3, which animal knoweth his owner, while Israel doth not know?","bible_ref":"Isaiah 1:3","verse_text":"The ox knoweth his owner, and the ass his master’s crib: but Israel doth not know, my people doth not consider."},"es":{"prompt":"Según Isaías 1:3, ¿qué animal conoce a su dueño, mientras Israel no conoce?","bible_ref":"Isaías 1:3","verse_text":"El buey conoce á su dueño, y el asno el pesebre de su señor: Israel no conoce, mi pueblo no tiene entendimiento."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O boi"},"fr":{"text":"Le bœuf"},"en":{"text":"The ox"},"es":{"text":"El buey"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O cavalo"},"fr":{"text":"Le cheval"},"en":{"text":"The horse"},"es":{"text":"El caballo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O cão"},"fr":{"text":"Le chien"},"en":{"text":"The dog"},"es":{"text":"El perro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O camelo"},"fr":{"text":"Le chameau"},"en":{"text":"The camel"},"es":{"text":"El camello"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-003","type":"choice","level":"medium","testament":"ot","book":"ISA","chapter":40,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Isaías 40:3 fala de preparar o caminho do SENHOR. Que lugar é nomeado nesse versículo?","bible_ref":"Isaías 40:3","verse_text":"Voz do que clama no deserto: Preparai o caminho do SENHOR; endireitai na terra estéril vereda ao nosso Deus."},"fr":{"prompt":"Ésaïe 40:3 parle de préparer le chemin de l’Éternel. Quel lieu est nommé dans ce verset ?","bible_ref":"Ésaïe 40:3","verse_text":"Une voix crie: Préparez au désert le chemin de l’Éternel, Aplanissez dans les lieux arides Une route pour notre Dieu."},"en":{"prompt":"Isaiah 40:3 speaks of preparing the way of the LORD. Which place is named in that verse?","bible_ref":"Isaiah 40:3","verse_text":"The voice of him that crieth in the wilderness, Prepare ye the way of the LORD, make straight in the desert a highway for our God."},"es":{"prompt":"Isaías 40:3 habla de preparar el camino de Jehová. ¿Qué lugar se nombra en ese versículo?","bible_ref":"Isaías 40:3","verse_text":"Voz que clama en el desierto: Barred camino á Jehová: enderezad calzada en la soledad á nuestro Dios."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O deserto"},"fr":{"text":"Le désert"},"en":{"text":"The wilderness"},"es":{"text":"El desierto"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O mar"},"fr":{"text":"La mer"},"en":{"text":"The sea"},"es":{"text":"La mar"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O templo"},"fr":{"text":"Le temple"},"en":{"text":"The temple"},"es":{"text":"El templo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O monte"},"fr":{"text":"La montagne"},"en":{"text":"The mountain"},"es":{"text":"El monte"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-004","type":"choice","level":"medium","testament":"ot","book":"JER","chapter":1,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Segundo Jeremias 1:11, o que viu Jeremias quando Deus lhe perguntou «Que vês?»","bible_ref":"Jeremias 1:11","verse_text":"E a palavra do SENHOR veio a mim, dizendo: O que tu vês, Jeremias? E eu disse: Vejo uma vara de amendoeira."},"fr":{"prompt":"Selon Jérémie 1:11, que vit Jérémie quand Dieu lui demanda « Que vois-tu ? »","bible_ref":"Jérémie 1:11","verse_text":"La parole de l’Éternel me fut adressée, en ces mots: Que vois-tu, Jérémie? Je répondis: Je vois une branche d’amandier."},"en":{"prompt":"According to Jeremiah 1:11, what did Jeremiah see when God asked “What seest thou?”","bible_ref":"Jeremiah 1:11","verse_text":"Moreover the word of the LORD came unto me, saying, Jeremiah, what seest thou? And I said, I see a rod of an almond tree."},"es":{"prompt":"Según Jeremías 1:11, ¿qué vio Jeremías cuando Dios le preguntó «¿Qué ves tú?»?","bible_ref":"Jeremías 1:11","verse_text":"Y la palabra de Jehová fué á mí, diciendo: ¿Qué ves tú, Jeremías? Y dije: Yo veo una vara de almendro."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma vara de amendoeira"},"fr":{"text":"Une branche d’amandier"},"en":{"text":"A rod of an almond tree"},"es":{"text":"Una vara de almendro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma vara de oliveira"},"fr":{"text":"Une branche d’olivier"},"en":{"text":"A rod of an olive tree"},"es":{"text":"Una vara de olivo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um ramo de figueira"},"fr":{"text":"Une branche de figuier"},"en":{"text":"A branch of a fig tree"},"es":{"text":"Una rama de higuera"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma videira"},"fr":{"text":"Une vigne"},"en":{"text":"A vine"},"es":{"text":"Una vid"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-005","type":"choice","level":"medium","testament":"ot","book":"LAM","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Lamentações 1:1, a cidade que era tão populosa tornou-se como quem?","bible_ref":"Lamentações 1:1","verse_text":"Como se senta solitária a cidade que era tão populosa! A grande entre as nações tornou-se como viúva, a senhora de províncias passou a ser escrava."},"fr":{"prompt":"Selon Lamentations 1:1, à qui la ville si peuplée est-elle devenue semblable ?","bible_ref":"Lamentations 1:1","verse_text":"Eh quoi! Elle est assise solitaire, cette ville si peuplée! Elle est semblable à une veuve! Grande entre les nations, souveraine parmi les états, Elle est réduite à la servitude!"},"en":{"prompt":"According to Lamentations 1:1, the city that was full of people is become as whom?","bible_ref":"Lamentations 1:1","verse_text":"How doth the city sit solitary, that was full of people! how is she become as a widow! she that was great among the nations, and princess among the provinces, how is she become tributary!"},"es":{"prompt":"Según Lamentaciones 1:1, ¿como quién se ha vuelto la ciudad populosa?","bible_ref":"Lamentaciones 1:1","verse_text":"¡Cómo está sentada sola la ciudad populosa! La grande entre las naciones se ha vuelto como viuda, la señora de provincias es hecha tributaria."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Uma viúva"},"fr":{"text":"Une veuve"},"en":{"text":"A widow"},"es":{"text":"Una viuda"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma rainha"},"fr":{"text":"Une reine"},"en":{"text":"A queen"},"es":{"text":"Una reina"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Uma noiva"},"fr":{"text":"Une fiancée"},"en":{"text":"A bride"},"es":{"text":"Una novia"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma mãe"},"fr":{"text":"Une mère"},"en":{"text":"A mother"},"es":{"text":"Una madre"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-006","type":"choice","level":"medium","testament":"ot","book":"EZK","chapter":1,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo Ezequiel 1:10, os quatro seres tinham rosto de homem, de leão, de boi e de quê?","bible_ref":"Ezequiel 1:10","verse_text":"E a aparência de seus rostos era como rosto de homem; e rosto de leão à direita nos quatro; e à esquerda rosto de boi nos quatro; também havia nos quatro um rosto de águia;"},"fr":{"prompt":"Selon Ézéchiel 1:10, les quatre animaux avaient une face d’homme, de lion, de bœuf et de quoi ?","bible_ref":"Ézéchiel 1:10","verse_text":"Quant à la figure de leurs faces, ils avaient tous une face d’homme, tous quatre une face de lion à droite, tous quatre une face de bœuf à gauche, et tous quatre une face d’aigle."},"en":{"prompt":"According to Ezekiel 1:10, the four had the face of a man, a lion, an ox and of what?","bible_ref":"Ezekiel 1:10","verse_text":"As for the likeness of their faces, they four had the face of a man, and the face of a lion, on the right side: and they four had the face of an ox on the left side; they four also had the face of an eagle."},"es":{"prompt":"Según Ezequiel 1:10, los cuatro tenían rostro de hombre, de león, de buey y ¿de qué más?","bible_ref":"Ezequiel 1:10","verse_text":"Y la figura de sus rostros era rostro de hombre; y rostro de león á la parte derecha en los cuatro; y á la izquierda rostro de buey en los cuatro; asimismo había en los cuatro rostro de águila."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De águia"},"fr":{"text":"D’aigle"},"en":{"text":"Of an eagle"},"es":{"text":"De águila"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"De cordeiro"},"fr":{"text":"D’agneau"},"en":{"text":"Of a lamb"},"es":{"text":"De cordero"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"De cavalo"},"fr":{"text":"De cheval"},"en":{"text":"Of a horse"},"es":{"text":"De caballo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De urso"},"fr":{"text":"D’ours"},"en":{"text":"Of a bear"},"es":{"text":"De oso"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-007","type":"choice","level":"medium","testament":"ot","book":"EZK","chapter":3,"verse_start":17,"verse_end":17,"texts":{"pt":{"prompt":"Segundo Ezequiel 3:17, o que fez Deus de Ezequiel sobre a casa de Israel?","bible_ref":"Ezequiel 3:17","verse_text":"Filho do homem, eu te pus por vigia sobre a casa de Israel; portanto tu ouvirás a palavra de minha boca, e os alertarás de minha parte."},"fr":{"prompt":"Selon Ézéchiel 3:17, qu’est-ce que Dieu fit d’Ézéchiel sur la maison d’Israël ?","bible_ref":"Ézéchiel 3:17","verse_text":"Fils de l’homme, je t’établis comme sentinelle sur la maison d’Israël. Tu écouteras la parole qui sortira de ma bouche, et tu les avertiras de ma part."},"en":{"prompt":"According to Ezekiel 3:17, what did God make Ezekiel unto the house of Israel?","bible_ref":"Ezekiel 3:17","verse_text":"Son of man, I have made thee a watchman unto the house of Israel: therefore hear the word at my mouth, and give them warning from me."},"es":{"prompt":"Según Ezequiel 3:17, ¿qué hizo Dios de Ezequiel para la casa de Israel?","bible_ref":"Ezequiel 3:17","verse_text":"Hijo del hombre, yo te he puesto por atalaya á la casa de Israel: oirás pues tú la palabra de mi boca, y amonestarlos has de mi parte."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um vigia"},"fr":{"text":"Une sentinelle"},"en":{"text":"A watchman"},"es":{"text":"Un atalaya"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Um rei"},"fr":{"text":"Un roi"},"en":{"text":"A king"},"es":{"text":"Un rey"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um juiz"},"fr":{"text":"Un juge"},"en":{"text":"A judge"},"es":{"text":"Un juez"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um capitão"},"fr":{"text":"Un capitaine"},"en":{"text":"A captain"},"es":{"text":"Un capitán"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-008","type":"choice","level":"medium","testament":"ot","book":"EZK","chapter":36,"verse_start":26,"verse_end":26,"texts":{"pt":{"prompt":"Segundo Ezequiel 36:26, que coração tiraria Deus de dentro do povo?","bible_ref":"Ezequiel 36:26","verse_text":"E vos darei um novo coração, e porei um novo espírito dentro de vós; e tirarei de vossa carne o coração de pedra, e vos darei um coração de carne."},"fr":{"prompt":"Selon Ézéchiel 36:26, quel cœur Dieu ôterait-il du peuple ?","bible_ref":"Ézéchiel 36:26","verse_text":"Je vous donnerai un cœur nouveau, et je mettrai en vous un esprit nouveau; j’ôterai de votre corps le cœur de pierre, et je vous donnerai un cœur de chair."},"en":{"prompt":"According to Ezekiel 36:26, which heart would God take away out of the people?","bible_ref":"Ezekiel 36:26","verse_text":"A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh."},"es":{"prompt":"Según Ezequiel 36:26, ¿qué corazón quitaría Dios del pueblo?","bible_ref":"Ezequiel 36:26","verse_text":"Y os daré corazón nuevo, y pondré espíritu nuevo dentro de vosotros; y quitaré de vuestra carne el corazón de piedra, y os daré corazón de carne."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O coração de pedra"},"fr":{"text":"Le cœur de pierre"},"en":{"text":"The stony heart"},"es":{"text":"El corazón de piedra"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O coração de carne"},"fr":{"text":"Le cœur de chair"},"en":{"text":"The heart of flesh"},"es":{"text":"El corazón de carne"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O coração de ferro"},"fr":{"text":"Le cœur de fer"},"en":{"text":"The heart of iron"},"es":{"text":"El corazón de hierro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O coração de gelo"},"fr":{"text":"Le cœur de glace"},"en":{"text":"The heart of ice"},"es":{"text":"El corazón de hielo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-009","type":"choice","level":"medium","testament":"ot","book":"HOS","chapter":8,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Segundo Oseias 8:7, os que semearam vento, o que colherão?","bible_ref":"Oseias 8:7","verse_text":"Porque semearam vento, colherão tempestade; não haverá colheita, nem a produção dará farinha; mesmo se a der, estrangeiros a tragarão."},"fr":{"prompt":"Selon Osée 8:7, ceux qui ont semé du vent, que moissonneront-ils ?","bible_ref":"Osée 8:7","verse_text":"Puisqu’ils ont semé du vent, ils moissonneront la tempête; Ils n’auront pas un épi de blé; Ce qui poussera ne donnera point de farine, Et s’il y en avait, des étrangers la dévoreraient."},"en":{"prompt":"According to Hosea 8:7, they that have sown the wind shall reap what?","bible_ref":"Hosea 8:7","verse_text":"For they have sown the wind, and they shall reap the whirlwind: it hath no stalk: the bud shall yield no meal: if so be it yield, the strangers shall swallow it up."},"es":{"prompt":"Según Oseas 8:7, los que sembraron viento, ¿qué segarán?","bible_ref":"Oseas 8:7","verse_text":"Porque sembraron viento, y torbellino segarán: no tendrán mies, ni el fruto hará harina; si la hiciere, extraños la tragarán."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Tempestade"},"fr":{"text":"La tempête"},"en":{"text":"The whirlwind"},"es":{"text":"Torbellino"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Chuva"},"fr":{"text":"La pluie"},"en":{"text":"The rain"},"es":{"text":"Lluvia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ouro"},"fr":{"text":"De l’or"},"en":{"text":"Gold"},"es":{"text":"Oro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Fogo"},"fr":{"text":"Le feu"},"en":{"text":"Fire"},"es":{"text":"Fuego"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-010","type":"choice","level":"medium","testament":"ot","book":"JOL","chapter":2,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo Joel 2:12, de que maneira pede o SENHOR que o povo se converta a ele?","bible_ref":"Joel 2:12","verse_text":"Por isso agora o SENHOR diz: Convertei-vos a mim com todo o vosso coração, com jejum, choro e pranto."},"fr":{"prompt":"Selon Joël 2:12, de quelle manière l’Éternel demande-t-il au peuple de revenir à lui ?","bible_ref":"Joël 2:12","verse_text":"Maintenant encore, dit l’Éternel, Revenez à moi de tout votre cœur, Avec des jeûnes, avec des pleurs et des lamentations!"},"en":{"prompt":"According to Joel 2:12, how does the LORD ask the people to turn to him?","bible_ref":"Joel 2:12","verse_text":"Therefore also now, saith the LORD, turn ye even to me with all your heart, and with fasting, and with weeping, and with mourning:"},"es":{"prompt":"Según Joel 2:12, ¿de qué manera pide Jehová que el pueblo se convierta a él?","bible_ref":"Joel 2:12","verse_text":"Por eso pues ahora, dice Jehová, convertíos á mí con todo vuestro corazón, con ayuno y lloro y llanto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"De todo o coração, com jejum e choro"},"fr":{"text":"De tout leur cœur, avec des jeûnes et des pleurs"},"en":{"text":"With all their heart, with fasting and weeping"},"es":{"text":"Con todo su corazón, con ayuno y lloro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com ofertas de ouro e prata"},"fr":{"text":"Avec des offrandes d’or et d’argent"},"en":{"text":"With offerings of gold and silver"},"es":{"text":"Con ofrendas de oro y plata"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com festas e cânticos"},"fr":{"text":"Avec des fêtes et des chants"},"en":{"text":"With feasts and songs"},"es":{"text":"Con fiestas y cantares"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com espadas e escudos"},"fr":{"text":"Avec des épées et des boucliers"},"en":{"text":"With swords and shields"},"es":{"text":"Con espadas y escudos"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-011","type":"choice","level":"medium","testament":"ot","book":"JOL","chapter":2,"verse_start":31,"verse_end":31,"texts":{"pt":{"prompt":"Segundo Joel 2:31, em que se tornará a lua antes do grande dia do SENHOR?","bible_ref":"Joel 2:31","verse_text":"O sol se tornará em trevas, e a lua em sangue, antes que venha o grande e temível dia do SENHOR."},"fr":{"prompt":"Selon Joël 2:31, en quoi la lune se changera-t-elle avant le grand jour de l’Éternel ?","bible_ref":"Joël 2:31","verse_text":"Le soleil se changera en ténèbres, Et la lune en sang, Avant l’arrivée du jour de l’Éternel, De ce jour grand et terrible."},"en":{"prompt":"According to Joel 2:31, into what shall the moon be turned before the great day of the LORD?","bible_ref":"Joel 2:31","verse_text":"The sun shall be turned into darkness, and the moon into blood, before the great and the terrible day of the LORD come."},"es":{"prompt":"Según Joel 2:31, ¿en qué se tornará la luna antes del gran día de Jehová?","bible_ref":"Joel 2:31","verse_text":"El sol se tornará en tinieblas, y la luna en sangre, antes que venga el día grande y espantoso de Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Em sangue"},"fr":{"text":"En sang"},"en":{"text":"Into blood"},"es":{"text":"En sangre"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Em fogo"},"fr":{"text":"En feu"},"en":{"text":"Into fire"},"es":{"text":"En fuego"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Em ouro"},"fr":{"text":"En or"},"en":{"text":"Into gold"},"es":{"text":"En oro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Em pó"},"fr":{"text":"En poussière"},"en":{"text":"Into dust"},"es":{"text":"En polvo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-012","type":"choice","level":"medium","testament":"ot","book":"AMO","chapter":8,"verse_start":11,"verse_end":11,"texts":{"pt":{"prompt":"Segundo Amós 8:11, que fome enviaria Deus à terra?","bible_ref":"Amós 8:11","verse_text":"Eis que vêm dias, diz o Senhor DEUS, nos quais enviarei fome à terra; fome não de pão, nem sede de água, mas sim de ouvir as palavras do SENHOR."},"fr":{"prompt":"Selon Amos 8:11, quelle faim Dieu enverrait-il dans le pays ?","bible_ref":"Amos 8:11","verse_text":"Voici, les jours viennent, dit le Seigneur, l’Éternel, Où j’enverrai la famine dans le pays, Non pas la disette du pain et la soif de l’eau, Mais la faim et la soif d’entendre les paroles de l’Éternel."},"en":{"prompt":"According to Amos 8:11, what famine would God send in the land?","bible_ref":"Amos 8:11","verse_text":"Behold, the days come, saith the Lord GOD, that I will send a famine in the land, not a famine of bread, nor a thirst for water, but of hearing the words of the LORD:"},"es":{"prompt":"Según Amós 8:11, ¿qué hambre enviaría Dios a la tierra?","bible_ref":"Amós 8:11","verse_text":"He aquí vienen días, dice el Señor Jehová, en los cuales enviaré hambre á la tierra, no hambre de pan, ni sed de agua, sino de oir palabra de Jehová."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Fome de ouvir as palavras do SENHOR"},"fr":{"text":"La faim d’entendre les paroles de l’Éternel"},"en":{"text":"A famine of hearing the words of the LORD"},"es":{"text":"Hambre de oír palabra de Jehová"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Fome de pão"},"fr":{"text":"La faim de pain"},"en":{"text":"A famine of bread"},"es":{"text":"Hambre de pan"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sede de água"},"fr":{"text":"La soif d’eau"},"en":{"text":"A thirst for water"},"es":{"text":"Sed de agua"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Fome de carne"},"fr":{"text":"La faim de viande"},"en":{"text":"A famine of meat"},"es":{"text":"Hambre de carne"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-013","type":"choice","level":"medium","testament":"ot","book":"JON","chapter":1,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Segundo Jonas 1:6, o que disse o capitão do navio a Jonas?","bible_ref":"Jonas 1:6","verse_text":"E o capitão do navio se aproximou dele, e lhe disse: Que há contigo, dorminhoco? Levanta-te, e clama a teu deus; talvez ele se lembre de nós, para que não pereçamos."},"fr":{"prompt":"Selon Jonas 1:6, que dit le pilote du navire à Jonas ?","bible_ref":"Jonas 1:6","verse_text":"Le pilote s’approcha de lui, et lui dit: Pourquoi dors-tu? Lève-toi, invoque ton Dieu! Peut-être voudra-t-il penser à nous, et nous ne périrons pas."},"en":{"prompt":"According to Jonah 1:6, what did the shipmaster say to Jonah?","bible_ref":"Jonah 1:6","verse_text":"So the shipmaster came to him, and said unto him, What meanest thou, O sleeper? arise, call upon thy God, if so be that God will think upon us, that we perish not."},"es":{"prompt":"Según Jonás 1:6, ¿qué dijo el maestre de la nave a Jonás?","bible_ref":"Jonás 1:6","verse_text":"Y el maestre de la nave se llegó á él, y le dijo: ¿Qué tienes, dormilón? Levántate, y clama á tu Dios; quizá él tendrá compasión de nosotros, y no pereceremos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"«Levanta-te e clama ao teu deus»"},"fr":{"text":"« Lève-toi, invoque ton Dieu »"},"en":{"text":"“Arise, call upon thy God”"},"es":{"text":"«Levántate, y clama a tu Dios»"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"«Salta para o mar»"},"fr":{"text":"« Saute dans la mer »"},"en":{"text":"“Jump into the sea”"},"es":{"text":"«Salta a la mar»"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"«Ajuda-nos a remar»"},"fr":{"text":"« Aide-nous à ramer »"},"en":{"text":"“Help us to row”"},"es":{"text":"«Ayúdanos a remar»"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"«Esconde-te no porão»"},"fr":{"text":"« Cache-toi dans la cale »"},"en":{"text":"“Hide thyself in the hold”"},"es":{"text":"«Escóndete en la bodega»"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-014","type":"choice","level":"medium","testament":"ot","book":"JON","chapter":3,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Segundo Jonas 3:8, além das pessoas, quem devia cobrir-se de saco em Nínive?","bible_ref":"Jonas 3:8","verse_text":"E que as pessoas e os animais se cubram de saco, e clamem fortemente a Deus; e convertam-se cada um de seu mau caminho, e da violência que está em suas mãos."},"fr":{"prompt":"Selon Jonas 3:8, outre les hommes, qui devait être couvert de sacs à Ninive ?","bible_ref":"Jonas 3:8","verse_text":"Que les hommes et les bêtes soient couverts de sacs, qu’ils crient à Dieu avec force, et qu’ils reviennent tous de leur mauvaise voie et des actes de violence dont leurs mains sont coupables!"},"en":{"prompt":"According to Jonah 3:8, besides man, who was to be covered with sackcloth in Nineveh?","bible_ref":"Jonah 3:8","verse_text":"But let man and beast be covered with sackcloth, and cry mightily unto God: yea, let them turn every one from his evil way, and from the violence that is in their hands."},"es":{"prompt":"Según Jonás 3:8, además de los hombres, ¿quién debía cubrirse de saco en Nínive?","bible_ref":"Jonás 3:8","verse_text":"Y que se cubran de saco los hombres y los animales, y clamen á Dios fuertemente: y conviértase cada uno de su mal camino, de la rapiña que está en sus manos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os animais"},"fr":{"text":"Les bêtes"},"en":{"text":"The beasts"},"es":{"text":"Los animales"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os reis vizinhos"},"fr":{"text":"Les rois voisins"},"en":{"text":"The neighbouring kings"},"es":{"text":"Los reyes vecinos"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os ídolos"},"fr":{"text":"Les idoles"},"en":{"text":"The idols"},"es":{"text":"Los ídolos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"As casas"},"fr":{"text":"Les maisons"},"en":{"text":"The houses"},"es":{"text":"Las casas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-015","type":"choice","level":"medium","testament":"ot","book":"HAB","chapter":2,"verse_start":14,"verse_end":14,"texts":{"pt":{"prompt":"Segundo Habacuque 2:14, a terra se encherá do conhecimento da glória do SENHOR como o quê?","bible_ref":"Habacuque 2:14","verse_text":"Porque a terra se encherá de conhecimento da glória do SENHOR, como as águas cobrem o mar."},"fr":{"prompt":"Selon Habacuc 2:14, la terre sera remplie de la connaissance de la gloire de l’Éternel comme quoi ?","bible_ref":"Habacuc 2:14","verse_text":"Car la terre sera remplie de la connaissance de la gloire de l’Éternel, Comme le fond de la mer par les eaux qui le couvrent."},"en":{"prompt":"According to Habakkuk 2:14, the earth shall be filled with the knowledge of the glory of the LORD as what?","bible_ref":"Habakkuk 2:14","verse_text":"For the earth shall be filled with the knowledge of the glory of the LORD, as the waters cover the sea."},"es":{"prompt":"Según Habacuc 2:14, la tierra será llena del conocimiento de la gloria de Jehová ¿como qué?","bible_ref":"Habacuc 2:14","verse_text":"Porque la tierra será llena de conocimiento de la gloria de Jehová, como las aguas cubren la mar."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Como as águas cobrem o mar"},"fr":{"text":"Comme les eaux couvrent le fond de la mer"},"en":{"text":"As the waters cover the sea"},"es":{"text":"Como las aguas cubren la mar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Como a areia cobre a praia"},"fr":{"text":"Comme le sable couvre le rivage"},"en":{"text":"As the sand covers the shore"},"es":{"text":"Como la arena cubre la playa"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Como as estrelas enchem o céu"},"fr":{"text":"Comme les étoiles remplissent le ciel"},"en":{"text":"As the stars fill the sky"},"es":{"text":"Como las estrellas llenan el cielo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Como a luz enche o dia"},"fr":{"text":"Comme la lumière remplit le jour"},"en":{"text":"As light fills the day"},"es":{"text":"Como la luz llena el día"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-016","type":"choice","level":"medium","testament":"ot","book":"HAG","chapter":1,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Segundo Ageu 1:6, onde punha o seu salário quem trabalhava a jornal?","bible_ref":"Ageu 1:6","verse_text":"Semeais muito, mas colheis pouco; comeis, mas não vos fartais; bebeis, mas não vos satisfazeis; vós vos vestis, mas não vos aqueceis; e o assalariado recebe seu salário em bolsa furada."},"fr":{"prompt":"Selon Aggée 1:6, où tombe le salaire de celui qui est à gages ?","bible_ref":"Aggée 1:6","verse_text":"Vous semez beaucoup, et vous recueillez peu, Vous mangez, et vous n’êtes pas rassasiés, Vous buvez, et vous n’êtes pas désaltérés, Vous êtes vêtus, et vous n’avez pas chaud; Le salaire de celui qui est à gages tombe dans un sac percé."},"en":{"prompt":"According to Haggai 1:6, where does he that earneth wages put them?","bible_ref":"Haggai 1:6","verse_text":"Ye have sown much, and bring in little; ye eat, but ye have not enough; ye drink, but ye are not filled with drink; ye clothe you, but there is none warm; and he that earneth wages earneth wages to put it into a bag with holes."},"es":{"prompt":"Según Haggeo 1:6, ¿dónde recibe su jornal el que anda a jornal?","bible_ref":"Hageo 1:6","verse_text":"Sembráis mucho, y encerráis poco; coméis, y no os hartáis; bebéis, y no os saciáis; os vestís, y no os calentáis; y el que anda á jornal recibe su jornal en trapo horadado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Numa bolsa furada"},"fr":{"text":"Dans un sac percé"},"en":{"text":"Into a bag with holes"},"es":{"text":"En un trapo horadado"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Num cofre de ouro"},"fr":{"text":"Dans un coffre d’or"},"en":{"text":"Into a chest of gold"},"es":{"text":"En un cofre de oro"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Debaixo da terra"},"fr":{"text":"Sous la terre"},"en":{"text":"Under the ground"},"es":{"text":"Debajo de la tierra"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"No tesouro do templo"},"fr":{"text":"Dans le trésor du temple"},"en":{"text":"Into the temple treasury"},"es":{"text":"En el tesoro del templo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-017","type":"choice","level":"medium","testament":"ot","book":"ZEC","chapter":11,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo Zacarias 11:12, quanto pesaram como salário?","bible_ref":"Zacarias 11:12","verse_text":"Pois eu havia lhes dito: Se vos parece bem aos vossos olhos, dai-me meu salário; e se não, deixai-o. E pesaram meu salário: trinta moedas de prata."},"fr":{"prompt":"Selon Zacharie 11:12, combien pesa-t-on pour le salaire ?","bible_ref":"Zacharie 11:12","verse_text":"Je leur dis: Si vous le trouvez bon, donnez-moi mon salaire; sinon, ne le donnez pas. Et ils pesèrent pour mon salaire trente sicles d’argent."},"en":{"prompt":"According to Zechariah 11:12, what did they weigh for the price?","bible_ref":"Zechariah 11:12","verse_text":"And I said unto them, If ye think good, give me my price; and if not, forbear. So they weighed for my price thirty pieces of silver."},"es":{"prompt":"Según Zacarías 11:12, ¿cuánto pesaron por el salario?","bible_ref":"Zacarías 11:12","verse_text":"Y díjeles: Si os parece bien, dadme mi salario; y si no, dejadlo. Y pesaron para mi salario treinta piezas de plata."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Trinta moedas de prata"},"fr":{"text":"Trente sicles d’argent"},"en":{"text":"Thirty pieces of silver"},"es":{"text":"Treinta piezas de plata"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Vinte moedas de prata"},"fr":{"text":"Vingt sicles d’argent"},"en":{"text":"Twenty pieces of silver"},"es":{"text":"Veinte piezas de plata"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cinquenta moedas de prata"},"fr":{"text":"Cinquante sicles d’argent"},"en":{"text":"Fifty pieces of silver"},"es":{"text":"Cincuenta piezas de plata"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cem moedas de ouro"},"fr":{"text":"Cent pièces d’or"},"en":{"text":"A hundred pieces of gold"},"es":{"text":"Cien piezas de oro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-018","type":"choice","level":"medium","testament":"ot","book":"ZEC","chapter":14,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo Zacarias 14:9, o que será o SENHOR sobre toda a terra?","bible_ref":"Zacarias 14:9","verse_text":"E o SENHOR será rei sobre toda a terra. Naquele dia o SENHOR será um, e seu nome um."},"fr":{"prompt":"Selon Zacharie 14:9, que sera l’Éternel de toute la terre ?","bible_ref":"Zacharie 14:9","verse_text":"L’Éternel sera roi de toute la terre; En ce jour-là, l’Éternel sera le seul Éternel, Et son nom sera le seul nom."},"en":{"prompt":"According to Zechariah 14:9, what shall the LORD be over all the earth?","bible_ref":"Zechariah 14:9","verse_text":"And the LORD shall be king over all the earth: in that day shall there be one LORD, and his name one."},"es":{"prompt":"Según Zacarías 14:9, ¿qué será Jehová sobre toda la tierra?","bible_ref":"Zacarías 14:9","verse_text":"Y Jehová será rey sobre toda la tierra. En aquel día Jehová será uno, y uno su nombre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Rei"},"fr":{"text":"Roi"},"en":{"text":"King"},"es":{"text":"Rey"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Pastor"},"fr":{"text":"Berger"},"en":{"text":"Shepherd"},"es":{"text":"Pastor"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Sacerdote"},"fr":{"text":"Sacrificateur"},"en":{"text":"Priest"},"es":{"text":"Sacerdote"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Profeta"},"fr":{"text":"Prophète"},"en":{"text":"Prophet"},"es":{"text":"Profeta"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-019","type":"choice","level":"medium","testament":"ot","book":"NAM","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Naum 1:3, o que são as nuvens para o SENHOR?","bible_ref":"Naum 1:3","verse_text":"O SENHOR é tardio para se irar, porém grande em poder; e não terá ao culpado por inocente. O SENHOR caminha entre a tempestade e o turbilhão, e as nuvens são o pó de seus pés."},"fr":{"prompt":"Selon Nahum 1:3, que sont les nuées pour l’Éternel ?","bible_ref":"Nahum 1:3","verse_text":"L’Éternel est lent à la colère, il est grand par sa force; Il ne laisse pas impuni. L’Éternel marche dans la tempête, dans le tourbillon; Les nuées sont la poussière de ses pieds."},"en":{"prompt":"According to Nahum 1:3, what are the clouds to the LORD?","bible_ref":"Nahum 1:3","verse_text":"The LORD is slow to anger, and great in power, and will not at all acquit the wicked: the LORD hath his way in the whirlwind and in the storm, and the clouds are the dust of his feet."},"es":{"prompt":"Según Nahum 1:3, ¿qué son las nubes para Jehová?","bible_ref":"Nahúm 1:3","verse_text":"Jehová es tardo para la ira, y grande en poder, y no tendrá al culpado por inocente. Jehová marcha entre la tempestad y turbión, y las nubes son el polvo de sus pies."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O pó dos seus pés"},"fr":{"text":"La poussière de ses pieds"},"en":{"text":"The dust of his feet"},"es":{"text":"El polvo de sus pies"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O seu manto"},"fr":{"text":"Son manteau"},"en":{"text":"His garment"},"es":{"text":"Su manto"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O seu trono"},"fr":{"text":"Son trône"},"en":{"text":"His throne"},"es":{"text":"Su trono"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os seus carros"},"fr":{"text":"Ses chars"},"en":{"text":"His chariots"},"es":{"text":"Sus carros"}}}]}$json$::