select public.upsert_bank_question($json${"id":"prof2-medium-020","type":"choice","level":"medium","testament":"ot","book":"OBA","chapter":1,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Obadias 1:3, onde habita aquele a quem a soberba do coração enganou?","bible_ref":"Obadias 1:3","verse_text":"A arrogância de teu coração te enganou, tu que habitas nas fendas das rochas, em tua alta morada; que dizes em teu coração: Quem me derrubará ao chão?"},"fr":{"prompt":"Selon Abdias 1:3, où habite celui que l’orgueil de son cœur a égaré ?","bible_ref":"Abdias 1:3","verse_text":"L’orgueil de ton cœur t’a égaré, Toi qui habites le creux des rochers, Qui t’assieds sur les hauteurs, Et qui dis en toi-même: Qui me précipitera jusqu’à terre?"},"en":{"prompt":"According to Obadiah 1:3, where dwells the one whom the pride of his heart hath deceived?","bible_ref":"Obadiah 1:3","verse_text":"The pride of thine heart hath deceived thee, thou that dwellest in the clefts of the rock, whose habitation is high; that saith in his heart, Who shall bring me down to the ground?"},"es":{"prompt":"Según Abdías 1:3, ¿dónde mora aquel a quien la soberbia de su corazón engañó?","bible_ref":"Abdías 1:3","verse_text":"La soberbia de tu corazón te ha engañado, tú que moras en las hendiduras de las peñas, en tu altísima morada; que dices en tu corazón: ¿Quién me derribará á tierra?"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nas fendas das rochas"},"fr":{"text":"Dans le creux des rochers"},"en":{"text":"In the clefts of the rock"},"es":{"text":"En las hendiduras de las peñas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Num vale profundo"},"fr":{"text":"Dans une vallée profonde"},"en":{"text":"In a deep valley"},"es":{"text":"En un valle profundo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Junto ao mar"},"fr":{"text":"Au bord de la mer"},"en":{"text":"By the sea"},"es":{"text":"Junto a la mar"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Em tendas no deserto"},"fr":{"text":"Sous des tentes au désert"},"en":{"text":"In tents in the wilderness"},"es":{"text":"En tiendas en el desierto"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-medium-021","type":"choice","level":"medium","testament":"ot","book":"MIC","chapter":7,"verse_start":6,"verse_end":6,"texts":{"pt":{"prompt":"Segundo Miqueias 7:6, quem são os inimigos do homem?","bible_ref":"Miqueias 7:6","verse_text":"Porque o filho despreza o pai, a filha se levanta contra sua mãe, a nora contra sua sogra; e os inimigos do homem são os de sua própria casa."},"fr":{"prompt":"Selon Michée 7:6, qui sont les ennemis de chacun ?","bible_ref":"Michée 7:6","verse_text":"Car le fils outrage le père, La fille se soulève contre sa mère, La belle-fille contre sa belle-mère; Chacun a pour ennemis les gens de sa maison."},"en":{"prompt":"According to Micah 7:6, who are a man’s enemies?","bible_ref":"Micah 7:6","verse_text":"For the son dishonoureth the father, the daughter riseth up against her mother, the daughter in law against her mother in law; a man’s enemies are the men of his own house."},"es":{"prompt":"Según Miqueas 7:6, ¿quiénes son los enemigos del hombre?","bible_ref":"Miqueas 7:6","verse_text":"Porque el hijo deshonra al padre, la hija se levanta contra la madre, la nuera contra su suegra: y los enemigos del hombre son los de su casa."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Os da sua própria casa"},"fr":{"text":"Les gens de sa maison"},"en":{"text":"The men of his own house"},"es":{"text":"Los de su casa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Os povos estrangeiros"},"fr":{"text":"Les peuples étrangers"},"en":{"text":"Foreign nations"},"es":{"text":"Los pueblos extranjeros"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Os animais do campo"},"fr":{"text":"Les bêtes des champs"},"en":{"text":"The beasts of the field"},"es":{"text":"Las bestias del campo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Os reis da terra"},"fr":{"text":"Les rois de la terre"},"en":{"text":"The kings of the earth"},"es":{"text":"Los reyes de la