select public.upsert_bank_question($json${"id":"prof2-medium-022","type":"verse","level":"medium","testament":"ot","book":"ISA","chapter":53,"verse_start":5,"verse_end":5,"texts":{"pt":{"prompt":"Porém ele foi ferido por nossas transgressões, e esmagado por nossas perversidades; o castigo que nos traz a paz estava sobre ele, e por suas feridas fomos _____.","bible_ref":"Isaías 53:5","verse_text":"Porém ele foi ferido por nossas transgressões, e esmagado por nossas perversidades; o castigo que nos traz a paz estava sobre ele, e por suas feridas fomos curados."},"fr":{"prompt":"Mais il était blessé pour nos péchés, Brisé pour nos iniquités; Le châtiment qui nous donne la paix est tombé sur lui, Et c’est par ses meurtrissures que nous sommes _____.","bible_ref":"Ésaïe 53:5","verse_text":"Mais il était blessé pour nos péchés, Brisé pour nos iniquités; Le châtiment qui nous donne la paix est tombé sur lui, Et c’est par ses meurtrissures que nous sommes guéris."},"en":{"prompt":"But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are _____.","bible_ref":"Isaiah 53:5","verse_text":"But he was wounded for our transgressions, he was bruised for our iniquities: the chastisement of our peace was upon him; and with his stripes we are healed."},"es":{"prompt":"Mas él herido fué por nuestras rebeliones, molido por nuestros pecados: el castigo de nuestra paz sobre él; y por su llaga fuimos nosotros _____.","bible_ref":"Isaías 53:5","verse_text":"Mas él herido fué por nuestras rebeliones, molido por nuestros pecados: el castigo de nuestra paz sobre él; y por su llaga fuimos nosotros curados."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"perdoados"},"fr":{"text":"pardonnés"},"en":{"text":"forgiven"},"es":{"text":"perdonados"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"salvos"},"fr":{"text":"sauvés"},"en":{"text":"saved"},"es":{"text":"salvos"}}},{"posi