select public.upsert_bank_question($json${"id":"prof2-hard-001","type":"choice","level":"hard","testament":"ot","book":"ISA","chapter":20,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Isaías 20:3, como andou Isaías, como sinal relativo ao Egito?","bible_ref":"Isaías 20:3","verse_text":"Então o SENHOR disse: Assim como meu servo Isaías anda nu e descalço, como sinal e presságio relativo ao Egito e a Cuxe,"},"fr":{"prompt":"Selon Ésaïe 20:3, comment Ésaïe marchait-il, comme signe pour l’Égypte ?","bible_ref":"Ésaïe 20:3","verse_text":"Et l’Éternel dit: De même que mon serviteur Ésaïe marche nu et déchaussé, ce qui sera dans trois ans un signe et un présage pour l’Égypte et pour l’Éthiopie,"},"en":{"prompt":"According to Isaiah 20:3, how did Isaiah walk, for a sign upon Egypt?","bible_ref":"Isaiah 20:3","verse_text":"And the LORD said, Like as my servant Isaiah hath walked naked and barefoot three years for a sign and wonder upon Egypt and upon Ethiopia;"},"es":{"prompt":"Según Isaías 20:3, ¿cómo anduvo Isaías, como señal sobre Egipto?","bible_ref":"Isaías 20:3","verse_text":"Y dijo Jehová: De la manera que anduvo mi siervo Isaías desnudo y descalzo tres años, señal y pronóstico sobre Egipto y sobre Etiopía;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nu e descalço"},"fr":{"text":"Nu et déchaussé"},"en":{"text":"Naked and barefoot"},"es":{"text":"Desnudo y descalzo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Vestido de saco"},"fr":{"text":"Vêtu d’un sac"},"en":{"text":"Clothed in sackcloth"},"es":{"text":"Vestido de saco"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com um jugo ao pescoço"},"fr":{"text":"Avec un joug sur le cou"},"en":{"text":"With a yoke on his neck"},"es":{"text":"Con un yugo al cuello"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"De cabeça rapada"},"fr":{"text":"La tête rasée"},"en":{"text":"With his head shaven"},"es":{"text":"Con la cabeza rapada"}}}]}$json$::jso