select public.upsert_bank_question($json${"id":"prof2-hard-002","type":"choice","level":"hard","testament":"ot","book":"ISA","chapter":8,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Isaías 8:3, que nome mandou o SENHOR dar ao filho da profetisa?","bible_ref":"Isaías 8:3","verse_text":"E vim até a profetisa, que concebeu e teve um filho; e o SENHOR me disse: Chama o nome dele de Maer-Salal-Has-Baz,"},"fr":{"prompt":"Selon Ésaïe 8:3, quel nom l’Éternel dit-il de donner au fils de la prophétesse ?","bible_ref":"Ésaïe 8:3","verse_text":"Je m’étais approché de la prophétesse; elle conçut, et elle enfanta un fils. L’Éternel me dit: Donne-lui pour nom Maher-Schalal-Chasch-Baz."},"en":{"prompt":"According to Isaiah 8:3, what name did the LORD say to give the prophetess’s son?","bible_ref":"Isaiah 8:3","verse_text":"And I went unto the prophetess; and she conceived, and bare a son. Then said the LORD to me, Call his name Maher-shalal-hash-baz."},"es":{"prompt":"Según Isaías 8:3, ¿qué nombre mandó Jehová poner al hijo de la profetisa?","bible_ref":"Isaías 8:3","verse_text":"Y juntéme con la profetisa, la cual concibió, y parió un hijo. Y díjome Jehová: Ponle por nombre Maher-salal-hash-baz."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Maer-Salal-Has-Baz"},"fr":{"text":"Maher-Schalal-Chasch-Baz"},"en":{"text":"Maher-shalal-hash-baz"},"es":{"text":"Maher-salal-hash-baz"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Sear-Jasube"},"fr":{"text":"Schear-Jaschub"},"en":{"text":"Shear-jashub"},"es":{"text":"Sear-jasub"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Jezreel"},"fr":{"text":"Jizreel"},"en":{"text":"Jezreel"},"es":{"text":"Jezreel"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Não-Meu-Povo"},"fr":{"text":"Lo-Ammi"},"en":{"text":"Lo-ammi"},"es":{"text":"Lo-ammi"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-003","type":"choice","level":"hard","testament":"ot","book":"ISA","chapter":45,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Isaías 45:1, que rei é chamado «ungido» do SENHOR?","bible_ref":"Isaías 45:1","verse_text":"Assim diz o SENHOR a seu ungido, Ciro, ao qual tomou pela sua mão direita, para abater as nações diante dele, e tirar a proteção dos lombos dos reis; para abrir diante de sua presença as portas, e as portas não se fecharão:"},"fr":{"prompt":"Selon Ésaïe 45:1, quel roi est appelé « oint » de l’Éternel ?","bible_ref":"Ésaïe 45:1","verse_text":"Ainsi parle l’Éternel à son oint, à Cyrus, Qu’il tient par la main, Pour terrasser les nations devant lui, Et pour relâcher la ceinture des rois, Pour lui ouvrir les portes, Afin qu’elles ne soient plus fermées;"},"en":{"prompt":"According to Isaiah 45:1, which king is called the LORD’s “anointed”?","bible_ref":"Isaiah 45:1","verse_text":"Thus saith the LORD to his anointed, to Cyrus, whose right hand I have holden, to subdue nations before him; and I will loose the loins of kings, to open before him the two leaved gates; and the gates shall not be shut;"},"es":{"prompt":"Según Isaías 45:1, ¿qué rey es llamado «ungido» de Jehová?","bible_ref":"Isaías 45:1","verse_text":"Así dice Jehová á su ungido, á Ciro, al cual tomé yo por su mano derecha, para sujetar gentes delante de él y desatar lomos de reyes; para abrir delante de él puertas, y las puertas no se cerrarán:"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Ciro"},"fr":{"text":"Cyrus"},"en":{"text":"Cyrus"},"es":{"text":"Ciro"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nabucodonosor"},"fr":{"text":"Nebucadnetsar"},"en":{"text":"Nebuchadnezzar"},"es":{"text":"Nabucodonosor"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dario"},"fr":{"text":"Darius"},"en":{"text":"Darius"},"es":{"text":"Darío"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ezequias"},"fr":{"text":"Ézéchias"},"en":{"text":"Hezekiah"},"es":{"text":"Ezechîas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-004","type":"choice","level":"hard","testament":"ot","book":"JER","chapter":32,"verse_start":9,"verse_end":9,"texts":{"pt":{"prompt":"Segundo Jeremias 32:9, por quanto comprou Jeremias o campo de Hanameel, em Anatote?","bible_ref":"Jeremias 32:9","verse_text":"Assim comprei a propriedade de Hanameel, filho de meu tio, a qual está em Anatote; e pesei para ele o dinheiro: dezessete siclos de prata."},"fr":{"prompt":"Selon Jérémie 32:9, pour combien Jérémie acheta-t-il le champ de Hanameel, à Anathoth ?","bible_ref":"Jérémie 32:9","verse_text":"J’achetai de Hanameel, fils de mon oncle, le champ qui est à Anathoth, et je lui pesai l’argent, dix-sept sicles d’argent."},"en":{"prompt":"According to Jeremiah 32:9, for how much did Jeremiah buy the field of Hanameel in Anathoth?","bible_ref":"Jeremiah 32:9","verse_text":"And I bought the field of Hanameel my uncle’s son, that was in Anathoth, and weighed him the money, even seventeen shekels of silver."},"es":{"prompt":"Según Jeremías 32:9, ¿por cuánto compró Jeremías la heredad de Hanameel en Anathoth?","bible_ref":"Jeremías 32:9","verse_text":"Y compré la heredad de Hanameel, hijo de mi tío, la cual estaba en Anathoth, y peséle el dinero: diecisiete siclos de plata."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Dezassete siclos de prata"},"fr":{"text":"Dix-sept sicles d’argent"},"en":{"text":"Seventeen shekels of silver"},"es":{"text":"Diecisiete siclos de plata"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Trinta siclos de prata"},"fr":{"text":"Trente sicles d’argent"},"en":{"text":"Thirty shekels of silver"},"es":{"text":"Treinta siclos de plata"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Cinquenta siclos de prata"},"fr":{"text":"Cinquante sicles d’argent"},"en":{"text":"Fifty shekels of silver"},"es":{"text":"Cincuenta siclos de plata"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sete siclos de 