select public.upsert_bank_question($json${"id":"prof2-hard-005","type":"choice","level":"hard","testament":"ot","book":"LAM","chapter":3,"verse_start":27,"verse_end":27,"texts":{"pt":{"prompt":"Segundo Lamentações 3:27, o que é bom o homem levar na sua juventude?","bible_ref":"Lamentações 3:27","verse_text":"É bom ao homem levar o jugo em sua juventude."},"fr":{"prompt":"Selon Lamentations 3:27, qu’est-il bon pour l’homme de porter dans sa jeunesse ?","bible_ref":"Lamentations 3:27","verse_text":"Il est bon pour l’homme De porter le joug dans sa jeunesse."},"en":{"prompt":"According to Lamentations 3:27, what is it good for a man to bear in his youth?","bible_ref":"Lamentations 3:27","verse_text":"It is good for a man that he bear the yoke in his youth."},"es":{"prompt":"Según Lamentaciones 3:27, ¿qué es bueno que el hombre lleve desde su mocedad?","bible_ref":"Lamentaciones 3:27","verse_text":"Bueno es al hombre, si llevare el yugo desde su mocedad."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O jugo"},"fr":{"text":"Le joug"},"en":{"text":"The yoke"},"es":{"text":"El yugo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A espada"},"fr":{"text":"L’épée"},"en":{"text":"The sword"},"es":{"text":"La espada"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A coroa"},"fr":{"text":"La couronne"},"en":{"text":"The crown"},"es":{"text":"La corona"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"O cajado"},"fr":{"text":"Le bâton"},"en":{"text":"The staff"},"es":{"text":"El cayado"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-006","type":"choice","level":"hard","testament":"ot","book":"EZK","chapter":24,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Segundo Ezequiel 24:18, o que aconteceu à tarde do dia em que Ezequiel falou ao povo?","bible_ref":"Ezequiel 24:18","verse_text":"E falei ao povo pela manhã, e minha mulher morreu à tarde; e pela manhã fiz como me fora mandado."},"fr":{"prompt":"Selon Ézéchiel 24:18, qu’arriva-t-il le soir du jour où Ézéchiel avait parlé au peuple ?","bible_ref":"Ézéchiel 24:18","verse_text":"J’avais parlé au peuple le matin, et ma femme mourut le soir. Le lendemain matin, je fis ce qui m’avait été ordonné."},"en":{"prompt":"According to Ezekiel 24:18, what happened at even on the day Ezekiel spake unto the people?","bible_ref":"Ezekiel 24:18","verse_text":"So I spake unto the people in the morning: and at even my wife died; and I did in the morning as I was commanded."},"es":{"prompt":"Según Ezequiel 24:18, ¿qué pasó a la tarde del día en que Ezequiel habló al pueblo?","bible_ref":"Ezequiel 24:18","verse_text":"Y hablé al pueblo por la mañana, y á la tarde murió mi mujer: y á la mañana hice como me fué mandado."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Morreu a mulher dele"},"fr":{"text":"Sa femme mourut"},"en":{"text":"His wife died"},"es":{"text":"Murió su mujer"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nasceu-lhe um filho"},"fr":{"text":"Un fils lui naquit"},"en":{"text":"A son was born to him"},"es":{"text":"Le nació un hijo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Caiu fogo do céu"},"fr":{"text":"Le feu tomba du ciel"},"en":{"text":"Fire fell from heaven"},"es":{"text":"Cayó fuego del cielo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A cidade foi inundada"},"fr":{"text":"La ville fut inondée"},"en":{"text":"The city was flooded"},"es":{"text":"La ciudad fue inundada"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-007","type":"choice","level":"hard","testament":"ot","book":"EZK","chapter":47,"verse_start":3,"verse_end":3,"texts":{"pt":{"prompt":"Segundo Ezequiel 47:3, depois de medidos os primeiros mil côvados, até onde chegava a água?","bible_ref":"Ezequiel 47:3","verse_text":"E quando aquele homem saiu para o oriente, tinha em sua mão um cordel de medir; ele mediu mil côvados, e me fez passar pelas águas, que chegavam aos tornozelos."},"fr":{"prompt":"Selon Ézéchiel 47:3, après les premières mille coudées mesurées, jusqu’où montait l’eau ?","bible_ref":"Ézéchiel 47:3","verse_text":"Lorsque l’homme s’avança vers l’orient, il avait dans la main un cordeau, et il mesura mille coudées; il me fit traverser l’eau, et j’avais de l’eau jusqu’aux chevilles."},"en":{"prompt":"According to Ezekiel 47:3, after the first thousand cubits were measured, how deep were the waters?","bible_ref":"Ezekiel 47:3","verse_text":"And when the man that had the line in his hand went forth eastward, he measured a thousand cubits, and he brought me through the waters; the waters were to the ankles."},"es":{"prompt":"Según Ezequiel 47:3, medidos los primeros mil codos, ¿hasta dónde llegaban las aguas?","bible_ref":"Ezequiel 47:3","verse_text":"Y saliendo el varón hacia el oriente, tenía un cordel en su mano; y midió mil codos, é hízome pasar por las aguas hasta los tobillos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Aos tornozelos"},"fr":{"text":"Aux chevilles"},"en":{"text":"To the ankles"},"es":{"text":"Hasta los tobillos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Ao peito"},"fr":{"text":"À la poitrine"},"en":{"text":"To the chest"},"es":{"text":"Hasta el pecho"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Aos ombros"},"fr":{"text":"Aux épaules"},"en":{"text":"To the shoulders"},"es":{"text":"Hasta los hombros"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ao pescoço"},"fr"