select public.upsert_bank_question($json${"id":"prof2-hard-008","type":"choice","level":"hard","testament":"ot","book":"HOS","chapter":3,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo Oseias 3:2, por quanta prata comprou Oseias a mulher, além da cevada?","bible_ref":"Oseias 3:2","verse_text":"Então eu a comprei para mim por quinze peças de prata, e um ômer e meio de cevada;"},"fr":{"prompt":"Selon Osée 3:2, pour combien d’argent Osée acheta-t-il la femme, outre l’orge ?","bible_ref":"Osée 3:2","verse_text":"Je l’achetai pour quinze sicles d’argent, un homer d’orge et un léthec d’orge."},"en":{"prompt":"According to Hosea 3:2, for how much silver did Hosea buy her, besides the barley?","bible_ref":"Hosea 3:2","verse_text":"So I bought her to me for fifteen pieces of silver, and for an homer of barley, and an half homer of barley:"},"es":{"prompt":"Según Oseas 3:2, ¿por cuánta plata compró Oseas a la mujer, además de la cebada?","bible_ref":"Oseas 3:2","verse_text":"Compréla entonces para mí por quince dineros de plata, y un homer y medio de cebada;"}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Quinze peças de prata"},"fr":{"text":"Quinze sicles d’argent"},"en":{"text":"Fifteen pieces of silver"},"es":{"text":"Quince dineros de plata"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Trinta peças de prata"},"fr":{"text":"Trente sicles d’argent"},"en":{"text":"Thirty pieces of silver"},"es":{"text":"Treinta dineros de plata"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dez peças de prata"},"fr":{"text":"Dix sicles d’argent"},"en":{"text":"Ten pieces of silver"},"es":{"text":"Diez dineros de plata"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Cem peças de prata"},"fr":{"text":"Cent sicles d’argent"},"en":{"text":"A hundred pieces of silver"},"es":{"text":"Cien dineros de plata"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-009","type":"choice","level":"hard","testament":"ot","book":"JOL","chapter":3,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo Joel 3:10, o que deve dizer o fraco?","bible_ref":"Joel 3:10","verse_text":"Fazei espadas de vossas enxadas, e lanças de vossas foices; diga o fraco: Sou forte."},"fr":{"prompt":"Selon Joël 3:10, que doit dire le faible ?","bible_ref":"Joël 3:10","verse_text":"De vos hoyaux forgez des épées, Et de vos serpes des lances! Que le faible dise: Je suis fort!"},"en":{"prompt":"According to Joel 3:10, what shall the weak say?","bible_ref":"Joel 3:10","verse_text":"Beat your plowshares into swords, and your pruninghooks into spears: let the weak say, I am strong."},"es":{"prompt":"Según Joel 3:10, ¿qué debe decir el flaco?","bible_ref":"Joel 3:10","verse_text":"Haced espadas de vuestros azadones, lanzas de vuestras hoces; diga el flaco: Fuerte soy."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"«Sou forte»"},"fr":{"text":"« Je suis fort »"},"en":{"text":"“I am strong”"},"es":{"text":"«Fuerte soy»"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"«Tenho medo»"},"fr":{"text":"« J’ai peur »"},"en":{"text":"“I am afraid”"},"es":{"text":"«Tengo miedo»"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"«Sou pequeno»"},"fr":{"text":"« Je suis petit »"},"en":{"text":"“I am small”"},"es":{"text":"«Pequeño soy»"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"«Estou cansado»"},"fr":{"text":"« Je suis las »"},"en":{"text":"“I am weary”"},"es":{"text":"«Cansado estoy»"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-010","type":"choice","level":"hard","testament":"ot","book":"AMO","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Amós 1:1, de que lugar eram os pastores entre os quais estava Amós?","bible_ref":"Amós 1:1","verse_text":"As palavras de Amós, que estava entre os pastores de Tecoa, as quais ele viu sobre Israel nos dias de Uzias rei de Judá, e nos dias de Jeroboão, filho de Joás, rei de Israel, dois anos antes do terremoto."},"fr":{"prompt":"Selon Amos 1:1, de quel lieu étaient les bergers parmi lesquels était Amos ?","bible_ref":"Amos 1:1","verse_text":"Paroles d’Amos, l’un des bergers de Tekoa, visions qu’il eut sur Israël, au temps d’Ozias, roi de Juda, et au temps de Jéroboam, fils de Joas, roi d’Israël, deux ans avant le tremblement de terre."},"en":{"prompt":"According to Amos 1:1, Amos was among the herdmen of which place?","bible_ref":"Amos 1:1","verse_text":"The words of Amos, who was among the herdmen of Tekoa, which he saw concerning Israel in the days of Uzziah king of Judah, and in the days of Jeroboam the son of Joash king of Israel, two years before the earthquake."},"es":{"prompt":"Según Amós 1:1, ¿de qué lugar eran los pastores entre los que estaba Amós?","bible_ref":"Amós 1:1","verse_text":"Las palabras de Amós, que fué entre los pastores de Tecoa, las cuales vió acerca de Israel en días de Uzzía rey de Judá, y en días de Jeroboam hijo de Joas rey de Israel, dos años antes del terremoto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Tecoa"},"fr":{"text":"Tekoa"},"en":{"text":"Tekoa"},"es":{"text":"Tecoa"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Anatote"},"fr":{"text":"Anathoth"},"en":{"text":"Anathoth"},"es":{"text":"Anathoth"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Siló"},"fr":{"text":"Silo"},"en":{"text":"Shiloh"},"es":{"text":"Silo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Belém"},"fr":{