select public.upsert_bank_question($json${"id":"prof2-hard-011","type":"choice","level":"hard","testament":"ot","book":"AMO","chapter":4,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Em Amós 4:1, como são chamados os que oprimem os pobres no monte de Samaria?","bible_ref":"Amós 4:1","verse_text":"Ouvi esta palavra, vós vacas de Basã, que estais no monte de Samaria; que oprimis os pobres, que quebrantais os necessitados, que dizeis a seus senhores: Trazei nossa bebida."},"fr":{"prompt":"Dans Amos 4:1, comment sont appelés ceux qui oppriment les misérables sur la montagne de Samarie ?","bible_ref":"Amos 4:1","verse_text":"Écoutez cette parole, génisses de Basan qui êtes sur la montagne de Samarie, Vous qui opprimez les misérables, qui écrasez les indigents, Et qui dites à vos maris: Apportez, et buvons!"},"en":{"prompt":"In Amos 4:1, what are those called who oppress the poor in the mountain of Samaria?","bible_ref":"Amos 4:1","verse_text":"Hear this word, ye kine of Bashan, that are in the mountain of Samaria, which oppress the poor, which crush the needy, which say to their masters, Bring, and let us drink."},"es":{"prompt":"En Amós 4:1, ¿cómo son llamados los que oprimen a los pobres en el monte de Samaria?","bible_ref":"Amós 4:1","verse_text":"Oid esta palabra, vacas de Basán, que estáis en el monte de Samaria, que oprimís los pobres, que quebrantáis los menesterosos, que decís á sus señores: Traed, y beberemos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Vacas de Basã"},"fr":{"text":"Génisses de Basan"},"en":{"text":"Kine of Bashan"},"es":{"text":"Vacas de Basán"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Vacas de Gileade"},"fr":{"text":"Génisses de Galaad"},"en":{"text":"Kine of Gilead"},"es":{"text":"Vacas de Galaad"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Vacas do Egito"},"fr":{"text":"Génisses d’Égypte"},"en":{"text":"Kine of Egypt"},"es":{"text":"Vacas de Egipto"}}},{"position":4,"is_correc