select public.upsert_bank_question($json${"id":"prof2-hard-012","type":"choice","level":"hard","testament":"ot","book":"OBA","chapter":1,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"Segundo Obadias 1:10, contra que irmão foi feita a violência?","bible_ref":"Obadias 1:10","verse_text":"Por causa da violência feita a teu irmão Jacó, a vergonha te cobrirá; e serás exterminado para sempre."},"fr":{"prompt":"Selon Abdias 1:10, contre quel frère la violence a-t-elle été commise ?","bible_ref":"Abdias 1:10","verse_text":"A cause de ta violence contre ton frère Jacob, Tu seras couvert de honte, Et tu seras exterminé pour toujours."},"en":{"prompt":"According to Obadiah 1:10, against which brother was the violence done?","bible_ref":"Obadiah 1:10","verse_text":"For thy violence against thy brother Jacob shame shall cover thee, and thou shalt be cut off for ever."},"es":{"prompt":"Según Abdías 1:10, ¿contra qué hermano fue hecha la injuria?","bible_ref":"Abdías 1:10","verse_text":"Por la injuria de tu hermano Jacob te cubrirá vergüenza, y serás talado para siempre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Jacob"},"fr":{"text":"Jacob"},"en":{"text":"Jacob"},"es":{"text":"Jacob"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Esaú"},"fr":{"text":"Ésaü"},"en":{"text":"Esau"},"es":{"text":"Esaú"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Ismael"},"fr":{"text":"Ismaël"},"en":{"text":"Ishmael"},"es":{"text":"Ismael"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Ló"},"fr":{"text":"Lot"},"en":{"text":"Lot"},"es":{"text":"Lot"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-013","type":"choice","level":"hard","testament":"ot","book":"MIC","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Miqueias 1:1, sobre que cidades viu Miqueias a palavra do SENHOR?","bible_ref":"Miqueias 1:1","verse_text":"Palavra do SENHOR que veio a Miqueias, o morastita, nos dias de Jotão, Acaz, e Ezequias, reis de Judá; que ele viu sobre Samaria e Jerusalém."},"fr":{"prompt":"Selon Michée 1:1, sur quelles villes porte la prophétie de Michée ?","bible_ref":"Michée 1:1","verse_text":"La parole de l’Éternel fut adressée à Michée, de Moréscheth, au temps de Jotham, d’Achaz, d’Ézéchias, rois de Juda, prophétie sur Samarie et Jérusalem."},"en":{"prompt":"According to Micah 1:1, concerning which cities did Micah see the word of the LORD?","bible_ref":"Micah 1:1","verse_text":"The word of the LORD that came to Micah the Morasthite in the days of Jotham, Ahaz, and Hezekiah, kings of Judah, which he saw concerning Samaria and Jerusalem."},"es":{"prompt":"Según Miqueas 1:1, ¿sobre qué ciudades vio Miqueas la palabra de Jehová?","bible_ref":"Miqueas 1:1","verse_text":"Palabra de Jehová que fué á Miqueas de Morasti en días de Jotham, Achâz, y Ezechîas, reyes de Judá: lo que vió sobre Samaria y Jerusalem."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Samaria e Jerusalém"},"fr":{"text":"Samarie et Jérusalem"},"en":{"text":"Samaria and Jerusalem"},"es":{"text":"Samaria y Jerusalem"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Nínive e Babilónia"},"fr":{"text":"Ninive et Babylone"},"en":{"text":"Nineveh and Babylon"},"es":{"text":"Nínive y Babilonia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Tiro e Sidom"},"fr":{"text":"Tyr et Sidon"},"en":{"text":"Tyre and Sidon"},"es":{"text":"Tiro y Sidón"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Sodoma e Gomorra"},"fr":{"text":"Sodome et Gomorrhe"},"en":{"text":"Sodom and Gomorrah"},"es"