select public.upsert_bank_question($json${"id":"prof2-hard-014","type":"choice","level":"hard","testament":"ot","book":"NAM","chapter":1,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Segundo Naum 1:1, como é identificado o profeta Naum?","bible_ref":"Naum 1:1","verse_text":"Revelação sobre Nínive. Livro da visão de Naum o elcosita."},"fr":{"prompt":"Selon Nahum 1:1, comment le prophète Nahum est-il désigné ?","bible_ref":"Nahum 1:1","verse_text":"Oracle sur Ninive. Livre de la prophétie de Nahum, d’Elkosch."},"en":{"prompt":"According to Nahum 1:1, how is the prophet Nahum described?","bible_ref":"Nahum 1:1","verse_text":"The burden of Nineveh. The book of the vision of Nahum the Elkoshite."},"es":{"prompt":"Según Nahum 1:1, ¿cómo se describe al profeta Nahum?","bible_ref":"Nahúm 1:1","verse_text":"Carga de Nínive. Libro de la visión de Nahum de El-kosh."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Era elcosita"},"fr":{"text":"Il était d’Elkosch"},"en":{"text":"The Elkoshite"},"es":{"text":"Era de El-kosh"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Era tisbita"},"fr":{"text":"Il était Thischbite"},"en":{"text":"The Tishbite"},"es":{"text":"Era thisbita"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Era morastita"},"fr":{"text":"Il était de Moréscheth"},"en":{"text":"The Morasthite"},"es":{"text":"Era de Morasti"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Era gibeonita"},"fr":{"text":"Il était de Gabaon"},"en":{"text":"The Gibeonite"},"es":{"text":"Era de Gabaón"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-015","type":"choice","level":"hard","testament":"ot","book":"HAB","chapter":3,"verse_start":19,"verse_end":19,"texts":{"pt":{"prompt":"Segundo Habacuque 3:19, Deus fará os pés do profeta como os de que animal?","bible_ref":"Habacuque 3:19","verse_text":"DEUS, o Senhor, é minha fortaleza; ele fará meus pés como os das corças, e me fará andar sobre meus lugares altos. (Para o regente, com instrumentos de cordas)."},"fr":{"prompt":"Selon Habacuc 3:19, Dieu rend les pieds du prophète semblables à ceux de quel animal ?","bible_ref":"Habacuc 3:19","verse_text":"L’Éternel, le Seigneur, est ma force; Il rend mes pieds semblables à ceux des biches, Et il me fait marcher sur mes lieux élevés. Au chef des chantres. Avec instruments à cordes."},"en":{"prompt":"According to Habakkuk 3:19, God will make the prophet’s feet like the feet of which animal?","bible_ref":"Habakkuk 3:19","verse_text":"The LORD God is my strength, and he will make my feet like hinds’ feet, and he will make me to walk upon mine high places. To the chief singer on my stringed instruments."},"es":{"prompt":"Según Habacuc 3:19, ¿como los de qué animal pondrá Dios los pies del profeta?","bible_ref":"Habacuc 3:19","verse_text":"Jehová el Señor es mi fortaleza, el cual pondrá mis pies como de ciervas, y me hará andar sobre mis alturas. Al jefe de los cantores sobre mis instrumentos de cuerdas."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Das corças"},"fr":{"text":"Des biches"},"en":{"text":"Hinds"},"es":{"text":"De ciervas"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Dos leões"},"fr":{"text":"Des lions"},"en":{"text":"Lions"},"es":{"text":"De leones"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Dos cavalos"},"fr":{"text":"Des chevaux"},"en":{"text":"Horses"},"es":{"text":"De caballos"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Das cabras"},"fr":{"text":"Des chèvres"},"en":{"text":"Goats"},"es":{"text":"De cabras"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-016","type":"choice","level":"hard","testament":"ot","book":"ZEP","chapter":1,"verse_start":12,"verse_end":12,"texts":{"pt":{"prompt":"Segundo Sofonias 1:12, com quê fará Deus busca em Jerusalém?","bible_ref":"Sofonias 1:12","verse_text":"E será naquele tempo, que farei busca em Jerusalém com lâmpadas, e punirei os homens que estão acomodados como sedimentos de vinho, os quais dizem em seu coração: O SENHOR nem fará bem nem mal."},"fr":{"prompt":"Selon Sophonie 1:12, avec quoi Dieu fouillera-t-il Jérusalem ?","bible_ref":"Sophonie 1:12","verse_text":"En ce temps-là, je fouillerai Jérusalem avec des lampes, Et je châtierai les hommes qui reposent sur leurs lies, Et qui disent dans leur cœur: L’Éternel ne fait ni bien ni mal."},"en":{"prompt":"According to Zephaniah 1:12, with what will God search Jerusalem?","bible_ref":"Zephaniah 1:12","verse_text":"And it shall come to pass at that time, that I will search Jerusalem with candles, and punish the men that are settled on their lees: that say in their heart, The LORD will not do good, neither will he do evil."},"es":{"prompt":"Según Sofonías 1:12, ¿con qué escudriñará Dios a Jerusalem?","bible_ref":"Sofonías 1:12","verse_text":"Y será en aquel tiempo, que yo escudriñaré á Jerusalem con candiles, y haré visitación sobre los hombres que están sentados sobre sus heces, los cuales dicen en su corazón: Jehová ni hará bien ni mal."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Com lâmpadas"},"fr":{"text":"Avec des lampes"},"en":{"text":"With candles"},"es":{"text":"Con candiles"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Com espadas"},"fr":{"text":"Avec des épées"},"en":{"text":"With swords"},"es":{"text":"Con espadas"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Com trombetas"},"fr":{"text":"Avec des trompettes"},"en":{"text":"With trumpets"},"es":{"text":"Con trompetas"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Com cães"},"fr":{"text":"Avec des chiens"},"en":{"text":"With dogs"},"es":{"text":"Con perros"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-017","type":"choice","level":"hard","testament":"ot","book":"ZEP","chapter":2,"verse_start":13,"verse_end":13,"texts":{"pt":{"prompt":"Segundo Sofonias 2:13, que cidade Deus tornaria em desolação, seca como um deserto?","bible_ref":"Sofonias 2:13","verse_text":"E ele estenderá sua mão contra o norte, e destruirá a Assíria, e tornará Nínive em desolação e em secura como deserto."},"fr":{"prompt":"Selon Sophonie 2:13, quelle ville Dieu ferait-il devenir une solitude, aride comme le désert ?","bible_ref":"Sophonie 2:13","verse_text":"Il étendra sa main sur le septentrion, Il détruira l’Assyrie, Et il fera de Ninive une solitude, Une terre aride comme le désert."},"en":{"prompt":"According to Zephaniah 2:13, which city would God make a desolation, dry like a wilderness?","bible_ref":"Zephaniah 2:13","verse_text":"And he will stretch out his hand against the north, and destroy Assyria; and will make Nineveh a desolation, and dry like a wilderness."},"es":{"prompt":"Según Sofonías 2:13, ¿qué ciudad pondría Dios en asolamiento, seca como un desierto?","bible_ref":"Sofonías 2:13","verse_text":"Y extenderá su mano sobre el aquilón, y destruirá al Assur, y pondrá á Nínive en asolamiento, y en secadal como un desierto."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Nínive"},"fr":{"text":"Ninive"},"en":{"text":"Nineveh"},"es":{"text":"Nínive"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Babilónia"},"fr":{"text":"Babylone"},"en":{"text":"Babylon"},"es":{"text":"Babilonia"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Damasco"},"fr":{"text":"Damas"},"en":{"text":"Damascus"},"es":{"text":"Damasco"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Tiro"},"fr":{"text":"Tyr"},"en":{"text":"Tyre"},"es":{"text":"Tiro"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-018","type":"choice","level":"hard","testament":"ot","book":"HAG","chapter":2,"verse_start":23,"verse_end":23,"texts":{"pt":{"prompt":"Segundo Ageu 2:23, como o que porá Deus Zorobabel, porque o escolheu?","bible_ref":"Ageu 2:23","verse_text":"Naquele dia, diz o SENHOR dos exércitos, eu te tomarei, Zorobabel, filho de Sealtiel, servo meu, diz o SENHOR, e te porei como anel de selar; porque eu te escolhi, diz o SENHOR dos exércitos."},"fr":{"prompt":"Selon Aggée 2:23, comme quoi Dieu gardera-t-il Zorobabel, parce qu’il l’a choisi ?","bible_ref":"Aggée 2:23","verse_text":"En ce jour-là, dit l’Éternel des armées, Je te prendrai, Zorobabel, fils de Schealthiel, Mon serviteur, dit l’Éternel, Et je te garderai comme un sceau; Car je t’ai choisi, dit l’Éternel des armées."},"en":{"prompt":"According to Haggai 2:23, what will God make Zerubbabel as, because he has chosen him?","bible_ref":"Haggai 2:23","verse_text":"In that day, saith the LORD of hosts, will I take thee, O Zerubbabel, my servant, the son of Shealtiel, saith the LORD, and will make thee as a signet: for I have chosen thee, saith the LORD of hosts."},"es":{"prompt":"Según Haggeo 2:23, ¿como qué pondrá Dios a Zorobabel, porque lo escogió?","bible_ref":"Hageo 2:23","verse_text":"En aquel día, dice Jehová de los ejércitos, te tomaré, oh Zorobabel, hijo de Sealtiel, siervo mío, dice Jehová, y ponerte he como anillo de sellar: porque yo te escogí, dice Jehová de los ejércitos."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um anel de selar"},"fr":{"text":"Un sceau"},"en":{"text":"A signet"},"es":{"text":"Un anillo de sellar"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma coroa"},"fr":{"text":"Une couronne"},"en":{"text":"A crown"},"es":{"text":"Una corona"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um cetro"},"fr":{"text":"Un sceptre"},"en":{"text":"A sceptre"},"es":{"text":"Un cetro"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Um escudo"},"fr":{"text":"Un bouclier"},"en":{"text":"A shield"},"es":{"text":"Un escudo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-019","type":"choice","level":"hard","testament":"ot","book":"ZEC","chapter":2,"verse_start":8,"verse_end":8,"texts":{"pt":{"prompt":"Segundo Zacarias 2:8, quem vos toca, toca em quê?","bible_ref":"Zacarias 2:8","verse_text":"Porque assim diz o SENHOR dos exércitos: Foi por causa da glória que ele me enviou às nações que vos despojaram; porque quem vos toca, toca a menina de seu olho."},"fr":{"prompt":"Selon Zacharie 2:8, celui qui vous touche, que touche-t-il ?","bible_ref":"Zacharie 2:8","verse_text":"Car ainsi parle l’Éternel des armées: Après cela, viendra la gloire! Il m’a envoyé vers les nations qui vous ont dépouillés; Car celui qui vous touche touche la prunelle de son œil."},"en":{"prompt":"According to Zechariah 2:8, he that toucheth you toucheth what?","bible_ref":"Zechariah 2:8","verse_text":"For thus saith the LORD of hosts; After the glory hath he sent me unto the nations which spoiled you: for he that toucheth you toucheth the apple of his eye."},"es":{"prompt":"Según Zacarías 2:8, el que os toca, ¿qué toca?","bible_ref":"Zacarías 2:8","verse_text":"Porque así ha dicho Jehová de los ejércitos: Después de la gloria me enviará él á las gentes que os despojaron: porque el que os toca, toca á la niña de su ojo."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"A menina do seu olho"},"fr":{"text":"La prunelle de son œil"},"en":{"text":"The apple of his eye"},"es":{"text":"La niña de su ojo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"O seu coração"},"fr":{"text":"Son cœur"},"en":{"text":"His heart"},"es":{"text":"Su corazón"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"O seu trono"},"fr":{"text":"Son trône"},"en":{"text":"His throne"},"es":{"text":"Su trono"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"A sua mão direita"},"fr":{"text":"Sa main droite"},"en":{"text":"His right hand"},"es":{"text":"Su mano derecha"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-020","type":"choice","level":"hard","testament":"ot","book":"MAL","chapter":4,"verse_start":2,"verse_end":2,"texts":{"pt":{"prompt":"Segundo Malaquias 4:2, o que nascerá para os que temem o nome do SENHOR?","bible_ref":"Malaquias 4:2","verse_text":"Mas para vós, que temeis o meu nome, o Sol da justiça nascerá, trazendo cura em suas asas; e saireis, e saltareis de alegria como bezerros do curral."},"fr":{"prompt":"Selon Malachie 4:2, qu’est-ce qui se lèvera pour ceux qui craignent le nom de l’Éternel ?","bible_ref":"Malachie 4:2","verse_text":"Mais pour vous qui craignez mon nom, se lèvera Le soleil de la justice, Et la guérison sera sous ses ailes; Vous sortirez, et vous sauterez comme les veaux d’une étable,"},"en":{"prompt":"According to Malachi 4:2, what shall arise unto them that fear the LORD’s name?","bible_ref":"Malachi 4:2","verse_text":"But unto you that fear my name shall the Sun of righteousness arise with healing in his wings; and ye shall go forth, and grow up as calves of the stall."},"es":{"prompt":"Según Malaquías 4:2, ¿qué nacerá para los que temen el nombre de Jehová?","bible_ref":"Malaquías 4:2","verse_text":"Mas á vosotros los que teméis mi nombre, nacerá el Sol de justicia, y en sus alas traerá salud: y saldréis, y saltaréis como becerros de la manada."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"O Sol da justiça"},"fr":{"text":"Le soleil de la justice"},"en":{"text":"The Sun of righteousness"},"es":{"text":"El Sol de justicia"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"A estrela da manhã"},"fr":{"text":"L’étoile du matin"},"en":{"text":"The morning star"},"es":{"text":"La estrella de la mañana"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"A lua cheia"},"fr":{"text":"La pleine lune"},"en":{"text":"The full moon"},"es":{"text":"La luna llena"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma nova cidade"},"fr":{"text":"Une ville nouvelle"},"en":{"text":"A new city"},"es":{"text":"Una nueva ciudad"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-021","type":"choice","level":"hard","testament":"ot","book":"MAL","chapter":3,"verse_start":16,"verse_end":16,"texts":{"pt":{"prompt":"Segundo Malaquias 3:16, o que foi escrito diante do SENHOR para os que o temem?","bible_ref":"Malaquias 3:16","verse_text":"Então aqueles que temeram ao SENHOR falaram cada um a seu próximo, e o SENHOR prestou atenção e ouviu; e foi escrito um livro de memória diante dele para os que temem ao SENHOR, e para os que se honraram o seu nome."},"fr":{"prompt":"Selon Malachie 3:16, qu’est-ce qui fut écrit devant l’Éternel pour ceux qui le craignent ?","bible_ref":"Malachie 3:16","verse_text":"Alors ceux qui craignent l’Éternel se parlèrent l’un à l’autre; L’Éternel fut attentif, et il écouta; Et un livre de souvenir fut écrit devant lui Pour ceux qui craignent l’Éternel Et qui honorent son nom."},"en":{"prompt":"According to Malachi 3:16, what was written before the LORD for them that feared him?","bible_ref":"Malachi 3:16","verse_text":"Then they that feared the LORD spake often one to another: and the LORD hearkened, and heard it, and a book of remembrance was written before him for them that feared the LORD, and that thought upon his name."},"es":{"prompt":"Según Malaquías 3:16, ¿qué fue escrito delante de Jehová para los que le temen?","bible_ref":"Malaquías 3:16","verse_text":"Entonces los que temen á Jehová hablaron cada uno á su compañero; y Jehová escuchó y oyó, y fué escrito libro de memoria delante de él para los que temen á Jehová, y para los que piensan en su nombre."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"Um livro de memória"},"fr":{"text":"Un livre de souvenir"},"en":{"text":"A book of remembrance"},"es":{"text":"Un libro de memoria"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"Uma nova lei"},"fr":{"text":"Une loi nouvelle"},"en":{"text":"A new law"},"es":{"text":"Una nueva ley"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"Um cântico novo"},"fr":{"text":"Un cantique nouveau"},"en":{"text":"A new song"},"es":{"text":"Un cántico nuevo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"Uma carta de divórcio"},"fr":{"text":"Une lettre de divorce"},"en":{"text":"A bill of divorcement"},"es":{"text":"Una carta de divorcio"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-022","type":"verse","level":"hard","testament":"ot","book":"EZK","chapter":18,"verse_start":20,"verse_end":20,"texts":{"pt":{"prompt":"A alma que pecar, essa _____; o filho não será punido pela maldade do pai, nem o pai será punido pela maldade do filho; a justiça do justo será sobre ele, e a perversidade do perverso será sobre ele.","bible_ref":"Ezequiel 18:20","verse_text":"A alma que pecar, essa morrerá; o filho não será punido pela maldade do pai, nem o pai será punido pela maldade do filho; a justiça do justo será sobre ele, e a perversidade do perverso será sobre ele."},"fr":{"prompt":"L’âme qui pèche, c’est celle qui _____. Le fils ne portera pas l’iniquité de son père, et le père ne portera pas l’iniquité de son fils. La justice du juste sera sur lui, et la méchanceté du méchant sera sur lui.","bible_ref":"Ézéchiel 18:20","verse_text":"L’âme qui pèche, c’est celle qui mourra. Le fils ne portera pas l’iniquité de son père, et le père ne portera pas l’iniquité de son fils. La justice du juste sera sur lui, et la méchanceté du méchant sera sur lui."},"en":{"prompt":"The soul that sinneth, it shall _____. The son shall not bear the iniquity of the father, neither shall the father bear the iniquity of the son: the righteousness of the righteous shall be upon him, and the wickedness of the wicked shall be upon him.","bible_ref":"Ezekiel 18:20","verse_text":"The soul that sinneth, it shall die. The son shall not bear the iniquity of the father, neither shall the father bear the iniquity of the son: the righteousness of the righteous shall be upon him, and the wickedness of the wicked shall be upon him."},"es":{"prompt":"El alma que pecare, esa _____: el hijo no llevará por el pecado del padre, ni el padre llevará por el pecado del hijo: la justicia del justo será sobre él, y la impiedad del impío será sobre él.","bible_ref":"Ezequiel 18:20","verse_text":"El alma que pecare, esa morirá: el hijo no llevará por el pecado del padre, ni el padre llevará por el pecado del hijo: la justicia del justo será sobre él, y la impiedad del impío será sobre él."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"fugirá"},"fr":{"text":"fuira"},"en":{"text":"flee"},"es":{"text":"huirá"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"viverá"},"fr":{"text":"vivra"},"en":{"text":"live"},"es":{"text":"vivirá"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"morrerá"},"fr":{"text":"mourra"},"en":{"text":"die"},"es":{"text":"morirá"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"chorará"},"fr":{"text":"pleurera"},"en":{"text":"weep"},"es":{"text":"llorará"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-023","type":"verse","level":"hard","testament":"ot","book":"LAM","chapter":5,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"Converte-nos, SENHOR, a ti, e seremos convertidos; renova os nossos _____ como antes;","bible_ref":"Lamentações 5:21","verse_text":"Converte-nos, SENHOR, a ti, e seremos convertidos; renova os nossos dias como antes;"},"fr":{"prompt":"Fais-nous revenir vers toi, ô Éternel, et nous reviendrons! Donne-nous encore des _____ comme ceux d’autrefois!","bible_ref":"Lamentations 5:21","verse_text":"Fais-nous revenir vers toi, ô Éternel, et nous reviendrons! Donne-nous encore des jours comme ceux d’autrefois!"},"en":{"prompt":"Turn thou us unto thee, O LORD, and we shall be turned; renew our _____ as of old.","bible_ref":"Lamentations 5:21","verse_text":"Turn thou us unto thee, O LORD, and we shall be turned; renew our days as of old."},"es":{"prompt":"Vuélvenos, oh Jehová, á ti, y nos volveremos: renueva nuestros _____ como al principio.","bible_ref":"Lamentaciones 5:21","verse_text":"Vuélvenos, oh Jehová, á ti, y nos volveremos: renueva nuestros días como al principio."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"campos"},"fr":{"text":"champs"},"en":{"text":"fields"},"es":{"text":"campos"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"muros"},"fr":{"text":"murs"},"en":{"text":"walls"},"es":{"text":"muros"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"dias"},"fr":{"text":"jours"},"en":{"text":"days"},"es":{"text":"días"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"corações"},"fr":{"text":"cœurs"},"en":{"text":"hearts"},"es":{"text":"corazones"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-024","type":"verse","level":"hard","testament":"ot","book":"OBA","chapter":1,"verse_start":21,"verse_end":21,"texts":{"pt":{"prompt":"E salvadores se levantarão no monte de Sião, para julgarem ao monte de Esaú; e o _____ pertencerá ao SENHOR.","bible_ref":"Obadias 1:21","verse_text":"E salvadores se levantarão no monte de Sião, para julgarem ao monte de Esaú; e o reino pertencerá ao SENHOR."},"fr":{"prompt":"Des libérateurs monteront sur la montagne de Sion, Pour juger la montagne d’Ésaü; Et à l’Éternel appartiendra le _____.","bible_ref":"Abdias 1:21","verse_text":"Des libérateurs monteront sur la montagne de Sion, Pour juger la montagne d’Ésaü; Et à l’Éternel appartiendra le règne."},"en":{"prompt":"And saviours shall come up on mount Zion to judge the mount of Esau; and the _____ shall be the LORD’s.","bible_ref":"Obadiah 1:21","verse_text":"And saviours shall come up on mount Zion to judge the mount of Esau; and the kingdom shall be the LORD’s."},"es":{"prompt":"Y vendrán salvadores al monte de Sión para juzgar al monte de Esaú; y el _____ será de Jehová.","bible_ref":"Abdías 1:21","verse_text":"Y vendrán salvadores al monte de Sión para juzgar al monte de Esaú; y el reino será de Jehová."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"templo"},"fr":{"text":"temple"},"en":{"text":"temple"},"es":{"text":"templo"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"deserto"},"fr":{"text":"désert"},"en":{"text":"wilderness"},"es":{"text":"desierto"}}},{"position":3,"is_correct":true,"texts":{"pt":{"text":"reino"},"fr":{"text":"règne"},"en":{"text":"kingdom"},"es":{"text":"reino"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"campo"},"fr":{"text":"champ"},"en":{"text":"field"},"es":{"text":"campo"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-025","type":"verse","level":"hard","testament":"ot","book":"JON","chapter":3,"verse_start":10,"verse_end":10,"texts":{"pt":{"prompt":"E Deus viu a atitude deles, que se converteram de seu mau caminho; então Deus se _____ do mal que tinha dito que lhes faria, e não o fez.","bible_ref":"Jonas 3:10","verse_text":"E Deus viu a atitude deles, que se converteram de seu mau caminho; então Deus se arrependeu do mal que tinha dito que lhes faria, e não o fez."},"fr":{"prompt":"Dieu vit qu’ils agissaient ainsi et qu’ils revenaient de leur mauvaise voie. Alors Dieu se _____ du mal qu’il avait résolu de leur faire, et il ne le fit pas.","bible_ref":"Jonas 3:10","verse_text":"Dieu vit qu’ils agissaient ainsi et qu’ils revenaient de leur mauvaise voie. Alors Dieu se repentit du mal qu’il avait résolu de leur faire, et il ne le fit pas."},"en":{"prompt":"And God saw their works, that they turned from their evil way; and God _____ of the evil, that he had said that he would do unto them; and he did it not.","bible_ref":"Jonah 3:10","verse_text":"And God saw their works, that they turned from their evil way; and God repented of the evil, that he had said that he would do unto them; and he did it not."},"es":{"prompt":"Y vió Dios lo que hicieron, que se convirtieron de su mal camino: y _____ del mal que había dicho les había de hacer, y no lo hizo.","bible_ref":"Jonás 3:10","verse_text":"Y vió Dios lo que hicieron, que se convirtieron de su mal camino: y arrepintióse del mal que había dicho les había de hacer, y no lo hizo."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"queixou"},"fr":{"text":"plaignit"},"en":{"text":"complained"},"es":{"text":"quejóse"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"cansou"},"fr":{"text":"lassa"},"en":{"text":"tired"},"es":{"text":"cansóse"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"gabou"},"fr":{"text":"vanta"},"en":{"text":"boasted"},"es":{