select public.upsert_bank_question($json${"id":"prof2-hard-026","type":"verse","level":"hard","testament":"ot","book":"MIC","chapter":7,"verse_start":18,"verse_end":18,"texts":{"pt":{"prompt":"Quem é Deus como tu, que perdoa a maldade, e ignora a transgressão do restante de sua herança? Ele não retém para sempre sua ira, porque ele tem prazer na _____.","bible_ref":"Miqueias 7:18","verse_text":"Quem é Deus como tu, que perdoa a maldade, e ignora a transgressão do restante de sua herança? Ele não retém para sempre sua ira, porque ele tem prazer na bondade."},"fr":{"prompt":"Quel Dieu est semblable à toi, Qui pardonnes l’iniquité, qui oublies les péchés Du reste de ton héritage? Il ne garde pas sa colère à toujours, Car il prend plaisir à la _____.","bible_ref":"Michée 7:18","verse_text":"Quel Dieu est semblable à toi, Qui pardonnes l’iniquité, qui oublies les péchés Du reste de ton héritage? Il ne garde pas sa colère à toujours, Car il prend plaisir à la miséricorde."},"en":{"prompt":"Who is a God like unto thee, that pardoneth iniquity, and passeth by the transgression of the remnant of his heritage? he retaineth not his anger for ever, because he delighteth in _____.","bible_ref":"Micah 7:18","verse_text":"Who is a God like unto thee, that pardoneth iniquity, and passeth by the transgression of the remnant of his heritage? he retaineth not his anger for ever, because he delighteth in mercy."},"es":{"prompt":"¿Qué Dios como tú, que perdonas la maldad, y olvidas el pecado del resto de su heredad? No retuvo para siempre su enojo, porque es amador de _____.","bible_ref":"Miqueas 7:18","verse_text":"¿Qué Dios como tú, que perdonas la maldad, y olvidas el pecado del resto de su heredad? No retuvo para siempre su enojo, porque es amador de misericordia."}},"options":[{"position":1,"is_correct":true,"texts":{"pt":{"text":"bondade"},"fr":{"text":"miséricorde"},"en":{"text":"mercy"},"es":{"text":"misericordia"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"glória"},"fr":{"text":"gloire"},"en":{"text":"glory"},"es":{"text":"gloria"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"vingança"},"fr":{"text":"vengeance"},"en":{"text":"vengeance"},"es":{"text":"venganza"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"força"},"fr":{"text":"force"},"en":{"text":"strength"},"es":{"text":"fortaleza"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-027","type":"verse","level":"hard","testament":"ot","book":"ZEC","chapter":13,"verse_start":7,"verse_end":7,"texts":{"pt":{"prompt":"Desperta-te, ó espada, contra o pastor e contra o homem que é companheiro, diz o SENHOR dos exércitos. Fere ao pastor, e as _____ se dispersarão; e voltarei minha mão sobre os pequenos.","bible_ref":"Zacarias 13:7","verse_text":"Desperta-te, ó espada, contra o pastor e contra o homem que é companheiro, diz o SENHOR dos exércitos. Fere ao pastor, e as ovelhas se dispersarão; e voltarei minha mão sobre os pequenos."},"fr":{"prompt":"Épée, lève-toi sur mon pasteur Et sur l’homme qui est mon compagnon! Dit l’Éternel des armées. Frappe le pasteur, et que les _____ se dispersent! Et je tournerai ma main vers les faibles.","bible_ref":"Zacharie 13:7","verse_text":"Épée, lève-toi sur mon pasteur Et sur l’homme qui est mon compagnon! Dit l’Éternel des armées. Frappe le pasteur, et que les brebis se dispersent! Et je tournerai ma main vers les faibles."},"en":{"prompt":"Awake, O sword, against my shepherd, and against the man that is my fellow, saith the LORD of hosts: smite the shepherd, and the _____ shall be scattered: and I will turn mine hand upon the little ones.","bible_ref":"Zechariah 13:7","verse_text":"Awake, O sword, against my shepherd, and against the man that is my fellow, saith the LORD of hosts: smite the shepherd, and the sheep shall be scattered: and I will turn mine hand upon the little ones."},"es":{"prompt":"Levántate, oh espada, sobre el pastor, y sobre el hombre compañero mío, dice Jehová de los ejércitos. Hiere al pastor, y se derramarán las _____: mas tornaré mi mano sobre los chiquitos.","bible_ref":"Zacarías 13:7","verse_text":"Levántate, oh espada, sobre el pastor, y sobre el hombre compañero mío, dice Jehová de los ejércitos. Hiere al pastor, y se derramarán las ovejas: mas tornaré mi mano sobre los chiquitos."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"cabras"},"fr":{"text":"chèvres"},"en":{"text":"goats"},"es":{"text":"cabras"}}},{"position":2,"is_correct":false,"texts":{"pt":{"text":"nações"},"fr":{"text":"nations"},"en":{"text":"nations"},"es":{"text":"naciones"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"pombas"},"fr":{"text":"colombes"},"en":{"text":"doves"},"es":{"text":"palomas"}}},{"position":4,"is_correct":true,"texts":{"pt":{"text":"ovelhas"},"fr":{"text":"brebis"},"en":{"text":"sheep"},"es":{"text":"ovejas"}}}]}$json$::jsonb);
select public.upsert_bank_question($json${"id":"prof2-hard-028","type":"verse","level":"hard","testament":"ot","book":"MAL","chapter":3,"verse_start":1,"verse_end":1,"texts":{"pt":{"prompt":"Eis que eu enviarei o meu mensageiro, que preparará o caminho adiante de mim; e de repente virá a seu _____ o Senhor a quem vós buscais, o mensageiro do pacto a quem vós desejais. Eis que ele vem, diz o SENHOR dos exércitos.","bible_ref":"Malaquias 3:1","verse_text":"Eis que eu enviarei o meu mensageiro, que preparará o caminho adiante de mim; e de repente virá a seu templo o Senhor a quem vós buscais, o mensageiro do pacto a quem vós desejais. Eis que ele vem, diz o SENHOR dos exércitos."},"fr":{"prompt":"Voici, j’enverrai mon messager; Il préparera le chemin devant moi. Et soudain entrera dans son _____ le Seigneur que vous cherchez; Et le messager de l’alliance que vous désirez, voici, il vient, Dit l’Éternel des armées.","bible_ref":"Malachie 3:1","verse_text":"Voici, j’enverrai mon messager; Il préparera le chemin devant moi. Et soudain entrera dans son temple le Seigneur que vous cherchez; Et le messager de l’alliance que vous désirez, voici, il vient, Dit l’Éternel des armées."},"en":{"prompt":"Behold, I will send my messenger, and he shall prepare the way before me: and the Lord, whom ye seek, shall suddenly come to his _____, even the messenger of the covenant, whom ye delight in: behold, he shall come, saith the LORD of hosts.","bible_ref":"Malachi 3:1","verse_text":"Behold, I will send my messenger, and he shall prepare the way before me: and the Lord, whom ye seek, shall suddenly come to his temple, even the messenger of the covenant, whom ye delight in: behold, he shall come, saith the LORD of hosts."},"es":{"prompt":"He aquí, yo envío mi mensajero, el cual preparará el camino delante de mí: y luego vendrá á su _____ el Señor á quien vosotros buscáis, y el ángel del pacto, á quien deseáis vosotros. He aquí viene, ha dicho Jehová de los ejércitos.","bible_ref":"Malaquías 3:1","verse_text":"He aquí, yo envío mi mensajero, el cual preparará el camino delante de mí: y luego vendrá á su templo el Señor á quien vosotros buscáis, y el ángel del pacto, á quien deseáis vosotros. He aquí viene, ha dicho Jehová de los ejércitos."}},"options":[{"position":1,"is_correct":false,"texts":{"pt":{"text":"monte"},"fr":{"text":"mont"},"en":{"text":"mountain"},"es":{"text":"monte"}}},{"position":2,"is_correct":true,"texts":{"pt":{"text":"templo"},"fr":{"text":"temple"},"en":{"text":"temple"},"es":{"text":"templo"}}},{"position":3,"is_correct":false,"texts":{"pt":{"text":"povo"},"fr":{"text":"peuple"},"en":{"text":"people"},"es":{"text":"pueblo"}}},{"position":4,"is_correct":false,"texts":{"pt":{"text":"trono"},"fr":{"text":"trône"},"en":{"text":"throne"},"es":{"text":"trono"}}}]}$json$::jsonb);
